/* AQA GCSE Biology — grade-separated exam-style practice questions.
   Each question: { g: grade 4-9, marks, q: question, scheme: [mark points], answer: model answer }
   Marked by self-assessment against the mark scheme. */
export default {
  subjectId: "biology",
  sections: {
    "1. Cell biology": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "Name the part of a cell that controls its activities.", scheme: ["Nucleus"], answer: "The nucleus." },
      { g: 4, marks: 1, q: "Name the jelly-like substance where most chemical reactions happen in a cell.", scheme: ["Cytoplasm"], answer: "The cytoplasm." },
      { g: 4, marks: 1, q: "Name the part of a cell that controls what enters and leaves it.", scheme: ["Cell membrane"], answer: "The cell membrane." },
      { g: 4, marks: 1, q: "In which part of a cell is most energy released during respiration?", scheme: ["Mitochondria"], answer: "The mitochondria." },
      { g: 4, marks: 1, q: "Name the green structures in plant cells that absorb light.", scheme: ["Chloroplasts"], answer: "Chloroplasts." },
      { g: 4, marks: 1, q: "Name the tough outer layer of a plant cell made of cellulose.", scheme: ["Cell wall"], answer: "The cell wall." },
      { g: 4, marks: 1, q: "What is the large fluid-filled space in a plant cell called?", scheme: ["(Permanent) vacuole"], answer: "The permanent vacuole." },
      { g: 4, marks: 1, q: "Are bacteria prokaryotic or eukaryotic cells?", scheme: ["Prokaryotic"], answer: "Prokaryotic." },
      { g: 4, marks: 1, q: "Give one example of a eukaryotic cell.", scheme: ["Animal cell / plant cell (any one)"], answer: "An animal cell (or a plant cell)." },
      { g: 4, marks: 1, q: "What piece of equipment is used to see individual cells?", scheme: ["(Light) microscope"], answer: "A microscope." },
      { g: 4, marks: 1, q: "Name the process by which one cell divides into two identical cells.", scheme: ["Mitosis"], answer: "Mitosis." },
      { g: 4, marks: 1, q: "What name is given to undifferentiated cells that can become other cell types?", scheme: ["Stem cells"], answer: "Stem cells." },
      { g: 4, marks: 1, q: "What is the movement of a substance from a high to a low concentration called?", scheme: ["Diffusion"], answer: "Diffusion." },
      { g: 4, marks: 1, q: "Name the site of protein synthesis in a cell.", scheme: ["Ribosome(s)"], answer: "The ribosomes." },
      { g: 4, marks: 1, q: "Give one structure found in a plant cell but not an animal cell.", scheme: ["Cell wall / chloroplast / permanent vacuole (any one)"], answer: "A cell wall (or chloroplast, or permanent vacuole)." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Define diffusion.", scheme: ["Net movement of particles from a high to a low concentration"], answer: "The net movement of particles from an area of higher concentration to an area of lower concentration." },
      { g: 5, marks: 2, q: "State the function of the nucleus.", scheme: ["Controls the cell/activities", "Contains the genetic material / DNA"], answer: "It controls the cell's activities and contains the genetic material (DNA)." },
      { g: 5, marks: 2, q: "Give two differences between a plant cell and an animal cell.", scheme: ["Plant has cell wall (animal doesn't)", "Plant has chloroplasts / permanent vacuole (animal doesn't)"], answer: "Plant cells have a cell wall and chloroplasts/permanent vacuole; animal cells do not." },
      { g: 5, marks: 2, q: "What is osmosis?", scheme: ["Movement of water across a partially permeable membrane", "From dilute (high water) to concentrated (low water) solution"], answer: "The diffusion of water across a partially permeable membrane from a dilute to a more concentrated solution." },
      { g: 5, marks: 2, q: "State two structures a bacterial cell has that an animal cell does not.", scheme: ["Cell wall", "Plasmid / single loop of DNA (any one more)"], answer: "A cell wall and plasmids (a single loop of DNA)." },
      { g: 5, marks: 2, q: "Name two sub-cellular structures found in both plant and animal cells.", scheme: ["Any two of: nucleus, cytoplasm, cell membrane, mitochondria, ribosomes"], answer: "Nucleus and mitochondria (or cytoplasm, cell membrane, ribosomes)." },
      { g: 5, marks: 1, q: "State the function of a ribosome.", scheme: ["Site of protein synthesis"], answer: "It is the site of protein synthesis." },
      { g: 5, marks: 1, q: "What is cell differentiation?", scheme: ["The process by which a cell becomes specialised for its function"], answer: "The process by which a cell becomes specialised to carry out a particular job." },
      { g: 5, marks: 1, q: "Give one example of a specialised animal cell.", scheme: ["Sperm / nerve / muscle / red blood cell (any one)"], answer: "A sperm cell (or nerve, muscle or red blood cell)." },
      { g: 5, marks: 1, q: "Give one example of a specialised plant cell.", scheme: ["Root hair / xylem / phloem cell (any one)"], answer: "A root hair cell (or xylem or phloem cell)." },
      { g: 5, marks: 1, q: "State the equation used to calculate magnification.", scheme: ["Magnification = image size ÷ real (actual) size"], answer: "Magnification = image size ÷ real size." },
      { g: 5, marks: 1, q: "What is meant by 'resolution' of a microscope?", scheme: ["Ability to distinguish two close points as separate"], answer: "The ability to distinguish two points that are close together as separate." },
      { g: 5, marks: 1, q: "State the function of chloroplasts.", scheme: ["Absorb light for photosynthesis (contain chlorophyll)"], answer: "They absorb light for photosynthesis; they contain chlorophyll." },
      { g: 5, marks: 2, q: "What is active transport?", scheme: ["Movement of substances from low to high concentration (against the gradient)", "Requires energy"], answer: "The movement of substances from a low to a high concentration, which requires energy." },
      { g: 5, marks: 1, q: "Name the type of cell division that produces two genetically identical cells.", scheme: ["Mitosis"], answer: "Mitosis." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why a root hair cell has a large surface area.", scheme: ["Increases surface area for absorption", "Faster uptake of water (osmosis) / minerals (active transport)"], answer: "The large surface area increases the rate at which it can absorb water by osmosis and minerals by active transport." },
      { g: 6, marks: 2, q: "Explain why muscle cells contain many mitochondria.", scheme: ["Mitochondria are the site of (aerobic) respiration", "Release energy for muscle contraction"], answer: "Mitochondria carry out respiration to release the energy needed for muscle contraction, so many are needed." },
      { g: 6, marks: 2, q: "A cell has a real length of 0.05 mm and appears 10 mm long in an image. Calculate the magnification.", scheme: ["magnification = 10 ÷ 0.05", "= ×200"], answer: "Magnification = image ÷ real = 10 ÷ 0.05 = ×200." },
      { g: 6, marks: 2, q: "Explain why an electron microscope can show more detail than a light microscope.", scheme: ["Higher magnification", "Higher resolution → smaller structures visible"], answer: "It has a higher magnification and resolution, so smaller sub-cellular structures can be seen." },
      { g: 6, marks: 3, q: "Describe how to prepare a slide to view onion epidermal cells.", scheme: ["Peel a thin layer of epidermis", "Place on slide and add a stain (e.g. iodine)", "Lower a coverslip to avoid air bubbles"], answer: "Peel a thin layer of epidermis, place it on a slide, add a drop of iodine stain, then lower a coverslip carefully to avoid air bubbles." },
      { g: 6, marks: 2, q: "Explain two adaptations of a sperm cell.", scheme: ["Tail/flagellum to swim to the egg", "Many mitochondria to release energy for movement"], answer: "It has a tail to swim to the egg and many mitochondria to release the energy needed for swimming." },
      { g: 6, marks: 2, q: "Explain why cells differentiate.", scheme: ["To become specialised", "So they carry out a specific function efficiently"], answer: "So they become specialised, allowing them to carry out a particular function efficiently." },
      { g: 6, marks: 1, q: "Convert 5 mm into micrometres (µm).", scheme: ["5000 µm"], answer: "5 mm × 1000 = 5000 µm." },
      { g: 6, marks: 2, q: "Explain why active transport requires energy.", scheme: ["Moves substances against the concentration gradient", "Energy (from respiration) needed to do this"], answer: "It moves substances against the concentration gradient (low to high), which needs energy from respiration." },
      { g: 6, marks: 2, q: "Explain why red blood cells have no nucleus.", scheme: ["More space/room inside the cell", "For more haemoglobin to carry oxygen"], answer: "Having no nucleus leaves more room for haemoglobin, so the cell can carry more oxygen." },
      { g: 6, marks: 2, q: "Explain why a plant may wilt when placed in a concentrated salt solution.", scheme: ["Water leaves cells by osmosis", "Cells become flaccid so the plant wilts"], answer: "Water leaves the cells by osmosis into the more concentrated solution, so the cells become flaccid and the plant wilts." },
      { g: 6, marks: 3, q: "Describe the function of xylem cells and how they are adapted.", scheme: ["Transport water and minerals", "Hollow tubes / no end walls", "Strengthened with lignin"], answer: "Xylem transports water and minerals; the cells are hollow with no end walls and are strengthened by lignin." },
      { g: 6, marks: 2, q: "Explain why bacteria can increase in number very quickly.", scheme: ["Divide by binary fission", "Rapidly in suitable conditions (warmth, nutrients)"], answer: "Bacteria divide rapidly by binary fission when conditions such as temperature and nutrients are suitable." },
      { g: 6, marks: 2, q: "Explain the role of stem cells found in a plant's meristem.", scheme: ["Can differentiate into any plant cell type", "Allow growth throughout life"], answer: "Meristem stem cells can differentiate into any type of plant cell, allowing the plant to grow throughout its life." },
      { g: 6, marks: 2, q: "An object is 0.1 mm and is viewed at ×50. Calculate its image size in mm.", scheme: ["image = magnification × real = 50 × 0.1", "= 5 mm"], answer: "Image size = magnification × real size = 50 × 0.1 = 5 mm." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Describe what happens during the cell cycle, including mitosis.", scheme: ["DNA replicates / chromosomes duplicate", "Cell grows and makes more sub-cellular structures", "Mitosis: chromosomes line up and are pulled apart to each end", "Cytoplasm and membrane divide → two identical cells"], answer: "The DNA replicates and the cell grows, making more sub-cellular structures. In mitosis the chromosomes line up in the centre and are pulled to opposite ends, then the cytoplasm and membrane divide to form two genetically identical cells." },
      { g: 7, marks: 3, q: "Explain how a root hair cell is adapted for absorbing water and minerals.", scheme: ["Large surface area for absorption", "Thin cell wall/membrane → short diffusion distance", "Many mitochondria for energy for active transport"], answer: "It has a large surface area for absorption, a thin surface for a short diffusion path, and many mitochondria to provide energy for the active transport of minerals." },
      { g: 7, marks: 3, q: "A cell appears 20 mm wide in an image taken at ×500 magnification. Calculate its real size and give the unit.", scheme: ["real = image ÷ magnification = 20 ÷ 500", "= 0.04 mm", "= 40 µm (accept either unit)"], answer: "Real size = image ÷ magnification = 20 ÷ 500 = 0.04 mm (40 µm)." },
      { g: 7, marks: 3, q: "Explain how stem cell treatment could help a patient who is paralysed.", scheme: ["Stem cells are unspecialised", "Can differentiate into nerve cells", "Replace/repair damaged nerve cells"], answer: "Stem cells are unspecialised, so they can differentiate into new nerve cells to replace those that were damaged and restore function." },
      { g: 7, marks: 4, q: "Describe how you would investigate the effect of sugar concentration on osmosis in potato tissue.", scheme: ["Cut equal-sized potato chips", "Measure starting mass; place in a range of sugar concentrations", "Same time/temperature; remove and reweigh", "Calculate percentage change in mass"], answer: "Cut equal-sized chips, measure their mass, then place each in a different sugar concentration for the same time and temperature. Reweigh them and calculate the percentage change in mass." },
      { g: 7, marks: 3, q: "A potato chip gains mass in pure water. Explain why.", scheme: ["Cell solution is more concentrated than water", "Water enters by osmosis", "Across the partially permeable membrane"], answer: "The cell's solution is more concentrated than the water, so water moves into the cells by osmosis across the partially permeable membrane, increasing the mass." },
      { g: 7, marks: 3, q: "Explain the difference between diffusion, osmosis and active transport.", scheme: ["Diffusion: particles high→low concentration", "Osmosis: water across a partially permeable membrane", "Active transport: low→high, requires energy"], answer: "Diffusion moves particles from high to low concentration; osmosis is water moving across a partially permeable membrane; active transport moves substances low to high and needs energy." },
      { g: 7, marks: 3, q: "Describe how to use a light microscope to focus on a specimen.", scheme: ["Start on the lowest power objective lens", "Use the coarse focus to bring into view", "Use fine focus for a sharp image (then increase magnification)"], answer: "Start with the lowest power lens, use the coarse focus to roughly focus, then the fine focus to sharpen, before switching to a higher magnification." },
      { g: 7, marks: 2, q: "A single bacterium divides every 20 minutes. How many bacteria are there after 2 hours? Show your working.", scheme: ["2 hours = 6 divisions", "2^6 = 64"], answer: "In 2 hours there are 6 divisions, so 2^6 = 64 bacteria." },
      { g: 7, marks: 3, q: "Explain why most specialised animal cells cannot change into other cell types, unlike plant cells.", scheme: ["Animal cells differentiate early / permanently", "Lose the ability to differentiate", "Plants keep this ability (meristems) throughout life"], answer: "Most animal cells differentiate early and permanently, losing the ability to become other cells, whereas plant cells in meristems keep this ability throughout life." },
      { g: 7, marks: 3, q: "Explain why the villi in the small intestine and root hair cells both have a large surface area.", scheme: ["Increase surface area", "Faster rate of absorption/exchange", "Of nutrients / water and minerals"], answer: "A large surface area increases the rate of absorption — of nutrients in the villi and of water and minerals in root hair cells." },
      { g: 7, marks: 3, q: "Explain why therapeutic cloning could reduce the risk of a transplant being rejected.", scheme: ["Stem cells produced are genetically identical to the patient", "Same antigens / not recognised as foreign", "So not rejected by the immune system"], answer: "The stem cells are genetically identical to the patient, so they have the same antigens and are not attacked by the immune system, reducing rejection." },
      { g: 7, marks: 3, q: "Compare the roles of mitosis in growth, repair and reproduction.", scheme: ["Produces genetically identical cells", "Growth (more cells) and repair (replace damaged cells)", "Asexual reproduction (identical offspring)"], answer: "Mitosis produces genetically identical cells used for growth, to repair and replace damaged cells, and for asexual reproduction." },
      { g: 7, marks: 3, q: "Explain why high magnification alone is not enough to see fine detail of a cell.", scheme: ["Magnification only enlarges the image", "Resolution needed to see detail/separate points", "Low resolution → blurred even if enlarged"], answer: "Magnification only enlarges the image; without high resolution the image is blurred, because resolution determines how much detail can be seen." },
      { g: 7, marks: 2, q: "Convert a real width of 8 µm seen at ×2000 into the image size in mm.", scheme: ["image = 2000 × 8 = 16000 µm", "= 16 mm"], answer: "Image = magnification × real = 2000 × 8 = 16 000 µm = 16 mm." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain fully how the mass of a potato chip changes when placed in solutions of different concentration.", scheme: ["In dilute solution water enters by osmosis → mass increases", "In concentrated solution water leaves → mass decreases", "At equal concentration no net movement → no change", "Movement across partially permeable membrane down water potential gradient"], answer: "In a dilute solution water enters the cells by osmosis so the chip gains mass; in a concentrated solution water leaves so it loses mass; when the concentrations are equal there is no net movement and no change, as water moves across the partially permeable membrane down its water potential gradient." },
      { g: 8, marks: 4, q: "Compare the structures of prokaryotic and eukaryotic cells.", scheme: ["Eukaryotic has a nucleus; prokaryotic does not (DNA free/loop)", "Eukaryotic has membrane-bound organelles (e.g. mitochondria); prokaryotic does not", "Prokaryotic has plasmids", "Prokaryotic cells are much smaller"], answer: "Eukaryotic cells have a nucleus and membrane-bound organelles such as mitochondria; prokaryotic cells have no nucleus (DNA is a single loop), have plasmids, no membrane-bound organelles, and are much smaller." },
      { g: 8, marks: 4, q: "Explain how a sperm cell is adapted to its function.", scheme: ["Tail/flagellum to swim to the egg", "Many mitochondria to release energy for movement", "Acrosome contains enzymes to penetrate the egg", "Haploid nucleus / streamlined shape"], answer: "It has a tail to swim, many mitochondria to release energy for swimming, an acrosome with enzymes to digest through the egg membrane, and a haploid nucleus carrying the genetic material." },
      { g: 8, marks: 4, q: "Explain the importance of mitosis in a multicellular organism.", scheme: ["Produces genetically identical (diploid) cells", "Used for growth", "Used for repair/replacement of cells", "Maintains genetic consistency between cells"], answer: "Mitosis produces genetically identical diploid cells used for growth and to repair or replace damaged cells, ensuring all body cells have the same genetic information." },
      { g: 8, marks: 3, q: "A student divides an image size in mm by a real size in µm to find magnification and gets a strange answer. Explain the error and how to correct it.", scheme: ["Units must be the same before dividing", "Convert mm to µm (×1000) or µm to mm (÷1000)", "Then magnification = image ÷ real"], answer: "Both measurements must be in the same units. They should convert the mm value to µm (×1000), or the µm value to mm, before dividing image size by real size." },
      { g: 8, marks: 4, q: "Explain, in terms of osmosis, why an animal cell may burst in pure water but a plant cell does not.", scheme: ["Water enters both by osmosis", "Plant cell wall is strong/inelastic → resists, becomes turgid", "Animal cell has no wall", "So animal cell swells and bursts (lyses)"], answer: "Water enters both cells by osmosis. The plant cell wall is strong and resists the pressure so the cell becomes turgid, but the animal cell has no wall, so it keeps swelling until it bursts." },
      { g: 8, marks: 4, q: "Explain how a root hair cell is adapted specifically for the active transport of mineral ions.", scheme: ["Many mitochondria", "Carry out respiration to release energy/ATP", "Energy used to move ions against the gradient", "Large surface area increases uptake"], answer: "It has many mitochondria that release energy by respiration; this energy powers active transport of mineral ions against the concentration gradient, and its large surface area increases the amount absorbed." },
      { g: 8, marks: 3, q: "Explain why cancer can be described as uncontrolled cell division.", scheme: ["Changes/mutations in genes controlling the cell cycle", "Cells divide uncontrollably by mitosis", "Form a mass/tumour"], answer: "Changes in the genes that control the cell cycle cause cells to divide uncontrollably by mitosis, forming a tumour." },
      { g: 8, marks: 4, q: "Evaluate the use of embryonic stem cells to treat disease.", scheme: ["Benefit: can differentiate into any cell type / treat many conditions", "Benefit: could cure diseases and reduce suffering", "Risk: destroys embryos → ethical/religious objections", "Risk: possible rejection or transfer of viral infection"], answer: "Embryonic stem cells can become any cell type and could treat many conditions, reducing suffering. However, using them destroys embryos, raising ethical and religious objections, and there are risks of rejection or passing on viral infections." },
      { g: 8, marks: 3, q: "Explain how differentiation differs between plant and animal cells.", scheme: ["Most animal cells differentiate once, early, and permanently", "Plant cells can differentiate throughout life", "Plants keep undifferentiated cells in meristems"], answer: "Most animal cells differentiate early and permanently, while many plant cells can differentiate throughout life because plants keep undifferentiated cells in their meristems." },
      { g: 8, marks: 3, q: "Describe how you would ensure your potato osmosis investigation gives valid, comparable results.", scheme: ["Control variables (temperature, chip size/surface area, time, volume)", "Repeat and calculate a mean", "Use percentage change in mass to compare fairly"], answer: "Keep temperature, chip size, time and solution volume the same, repeat each concentration and take a mean, and use the percentage change in mass so different starting masses can be compared fairly." },
      { g: 8, marks: 3, q: "Explain why electron microscopes greatly improved our understanding of cells.", scheme: ["Much higher resolution and magnification", "Revealed sub-cellular structures/organelles not visible with light microscopes", "e.g. internal structure of mitochondria"], answer: "Electron microscopes have far higher magnification and resolution, so they revealed sub-cellular structures such as the internal detail of mitochondria that light microscopes could not show." },
      { g: 8, marks: 4, q: "Evaluate therapeutic cloning as a way to treat patients.", scheme: ["Advantage: cells genetically identical → no rejection", "Advantage: could replace damaged tissues/organs", "Disadvantage: expensive and technically difficult", "Disadvantage: ethical concerns about embryos"], answer: "Therapeutic cloning produces cells identical to the patient so they are not rejected and could replace damaged tissue, but it is expensive, technically difficult, and raises ethical concerns about creating and using embryos." },
      { g: 8, marks: 3, q: "A number of bacteria double each division. Explain why the population grows exponentially and give the number after 8 divisions from one cell.", scheme: ["Each cell divides into two → number doubles each time", "Pattern is 2^n", "2^8 = 256"], answer: "Each division doubles the number of cells, so the population follows 2^n and grows exponentially. After 8 divisions there are 2^8 = 256 bacteria." },
      { g: 8, marks: 3, q: "Explain why meristem stem cells are useful to a farmer growing crops.", scheme: ["Can be used to clone plants quickly", "Produce many genetically identical plants", "With desirable features (e.g. disease resistance, high yield)"], answer: "Meristem cells can clone plants quickly, producing many identical plants with desirable features such as disease resistance or high yield." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Evaluate the use of stem cells in medicine, including different sources and the issues involved.", scheme: ["Sources: embryonic (any cell), adult (limited), plant meristem", "Benefits: treat diabetes, paralysis; differentiate into needed cells", "Therapeutic cloning → genetically identical, no rejection", "Risks: rejection, viral transmission, possible tumour formation", "Ethical/religious objections to using embryos", "Justified conclusion"], answer: "Stem cells come from embryos (able to form any cell), adults (more limited) and plant meristems. They could treat conditions such as diabetes and paralysis by differentiating into the needed cells, and therapeutic cloning gives genetically identical cells that are not rejected. However, there are risks of rejection, viral transmission and tumours, and ethical or religious objections to destroying embryos. On balance, careful, regulated use is justified where the benefit to patients is great." },
      { g: 9, marks: 6, q: "Explain fully how water and mineral ions are absorbed by a root hair cell, and how the cell is adapted for this.", scheme: ["Water enters by osmosis down the water potential gradient", "Through the partially permeable membrane", "Mineral ions enter by active transport against the gradient", "Energy for this from respiration in mitochondria", "Large surface area increases uptake", "Thin surface → short diffusion distance"], answer: "Water enters by osmosis, moving down the water potential gradient through the partially permeable membrane. Mineral ions are absorbed by active transport against their concentration gradient, using energy released by respiration in the cell's many mitochondria. The large surface area increases uptake and the thin surface shortens the diffusion distance." },
      { g: 9, marks: 6, q: "Describe and explain the full cell cycle, and explain what can happen if it is not controlled.", scheme: ["Interphase: DNA replicates, cell grows, organelles duplicate", "Mitosis: chromosomes condense and line up", "Chromosomes pulled to opposite poles", "Cytokinesis: cytoplasm/membrane divide → two identical diploid cells", "Purpose: growth and repair", "Loss of control → uncontrolled division → tumour/cancer"], answer: "During interphase the DNA replicates, the cell grows and duplicates its organelles. In mitosis the chromosomes condense, line up in the middle and are pulled to opposite poles, then the cytoplasm and membrane divide (cytokinesis) into two identical diploid cells, used for growth and repair. If the cycle loses control, cells divide uncontrollably and form a tumour, which can lead to cancer." },
      { g: 9, marks: 6, q: "Compare light and electron microscopes, and explain how magnification is calculated, using an example.", scheme: ["Electron: higher magnification and resolution → see organelles", "Electron: expensive, large, specimens not living", "Light: cheaper, portable, living specimens, lower detail", "Magnification = image size ÷ real size", "Units must match before calculating", "Worked example (e.g. 10 mm image, 0.05 mm real = ×200)"], answer: "Electron microscopes have much higher magnification and resolution so reveal organelles, but are expensive and cannot view living specimens; light microscopes are cheaper and can view living cells but show less detail. Magnification = image size ÷ real size, with both in the same units — for example a 10 mm image of a 0.05 mm cell gives ×200." },
      { g: 9, marks: 6, q: "Explain how the potato osmosis practical can be used to find the concentration of the cell's internal solution (the isotonic point).", scheme: ["Cut equal chips, control variables, measure mass change", "Calculate percentage change in mass for each concentration", "Plot percentage change against concentration", "Positive = water entered; negative = water left", "Line crosses x-axis (0% change) where no net movement", "That concentration equals the cell solution (isotonic)"], answer: "Equal chips are placed in a range of concentrations with variables controlled, and the percentage change in mass is calculated and plotted against concentration. Positive values show water entering and negative values water leaving; where the line crosses zero there is no net movement, so that external concentration equals the cell's internal solution — the isotonic point." },
      { g: 9, marks: 6, q: "'Embryonic stem cells should always be used to cure disease.' Evaluate this statement.", scheme: ["For: pluripotent, can form any cell → treat many diseases", "For: reduce suffering / save lives", "Against: ethical view an embryo is a potential life", "Against: religious objections", "Against: risks of rejection, tumours; alternatives (adult/plant cells)", "Justified conclusion referencing the arguments"], answer: "Embryonic stem cells are pluripotent, so they could treat many diseases and reduce suffering. However, many argue an embryo is a potential life, and there are religious objections and medical risks such as tumour formation. Alternatives like adult or induced stem cells exist. Therefore their use can be justified in serious cases but should be regulated rather than used in every situation." },
      { g: 9, marks: 5, q: "Explain the relationship between a cell's surface area to volume ratio and exchange, and why large organisms need specialised systems.", scheme: ["Small cells have a large surface area : volume ratio", "Diffusion across the surface is fast enough", "As size increases, ratio decreases", "Diffusion distances too large / surface too small", "So large organisms need specialised exchange surfaces and transport systems"], answer: "Small cells have a large surface area to volume ratio, so substances can diffuse in and out fast enough. As organisms get larger this ratio falls and diffusion distances become too great, so large organisms need specialised exchange surfaces and transport systems to supply all their cells." },
      { g: 9, marks: 6, q: "Explain how three named specialised cells are each adapted to their functions.", scheme: ["Sperm: tail, mitochondria, acrosome enzymes → reach and fertilise egg", "Root hair: large SA, mitochondria → absorb water/minerals", "Nerve/red blood/other: relevant adaptation linked to function", "Each adaptation clearly linked to its role"], answer: "A sperm cell has a tail, many mitochondria and an acrosome so it can swim to and fertilise an egg. A root hair cell has a large surface area and many mitochondria to absorb water and minerals. A red blood cell has no nucleus and is biconcave to carry more oxygen — each adaptation is matched to the cell's function." },
      { g: 9, marks: 5, q: "Explain why active transport is essential in both root hair cells and the small intestine, and how the cells are adapted.", scheme: ["Absorbs ions/glucose against the concentration gradient", "Diffusion alone would not move them / gradient wrong way", "Requires energy from respiration", "Many mitochondria to supply this energy", "Large surface area to maximise absorption"], answer: "Both need to absorb substances (minerals in roots, glucose in the intestine) against their concentration gradient, which diffusion cannot do, so active transport is used. This needs energy from respiration, so the cells have many mitochondria, and their large surface area maximises absorption." },
      { g: 9, marks: 6, q: "Explain, in terms of water potential, what happens to plant and animal cells placed in dilute and concentrated solutions.", scheme: ["Water moves from high to low water potential by osmosis", "Dilute solution: water enters", "Plant → turgid; animal → swells/bursts (lysis)", "Concentrated solution: water leaves", "Plant → flaccid/plasmolysed; animal → shrinks (crenation)"], answer: "Water moves by osmosis from a high to a low water potential. In a dilute solution water enters: plant cells become turgid while animal cells may swell and burst. In a concentrated solution water leaves: plant cells become flaccid or plasmolysed and animal cells shrink." },
      { g: 9, marks: 5, q: "A drug stops mitochondria from working. Predict and explain the effects on a root hair cell.", scheme: ["Less/no energy released by respiration", "Active transport slows/stops → fewer mineral ions absorbed", "Cell division/growth slows (needs energy)", "Osmosis (water uptake) still occurs (no energy needed)", "Overall reduced mineral uptake and growth"], answer: "Without working mitochondria little energy is released by respiration, so active transport slows and fewer mineral ions are absorbed, and growth slows because division needs energy. Water uptake by osmosis still occurs as it needs no energy, but overall mineral absorption and growth are reduced." },
      { g: 9, marks: 6, q: "Describe how a fertilised egg gives rise to the many specialised cells of the body, and explain how they can differ despite identical genes.", scheme: ["Zygote divides by mitosis → many identical cells", "Cells differentiate into specialised types", "Form tissues, then organs, then systems", "All cells have the same genes", "Different genes switched on/off in each cell type", "So cells make different proteins → different structures/functions"], answer: "The fertilised egg divides repeatedly by mitosis to form many identical cells, which then differentiate into specialised cells forming tissues, organs and systems. Although every cell contains the same genes, different genes are switched on or off in each cell type, so they make different proteins and develop different structures and functions." },
      { g: 9, marks: 5, q: "Evaluate whether all cell division should be considered beneficial to an organism.", scheme: ["Beneficial: growth, repair, replacement of cells", "Beneficial: asexual reproduction in some organisms", "Harmful: uncontrolled division → tumours/cancer", "Controlled by the cell cycle", "Conclusion: beneficial only when controlled"], answer: "Cell division is beneficial for growth, repair and replacing cells, and for asexual reproduction in some organisms. However, when it is not controlled it causes tumours and cancer. Division is only beneficial when properly regulated by the cell cycle." },
      { g: 9, marks: 6, q: "Explain fully why an electron microscope, but not a light microscope, allowed scientists to see the detailed internal structure of organelles.", scheme: ["Resolution = smallest distance between two distinguishable points", "Light microscope limited by the wavelength of light", "Electron beam has a much shorter wavelength", "So far higher resolution and magnification", "Reveals internal structure of organelles (e.g. mitochondria)", "Light microscope image would be blurred at that scale"], answer: "Resolution is the smallest distance at which two points appear separate. Light microscopes are limited by the wavelength of light, so beyond a point the image blurs. Electrons have a much shorter wavelength, giving far higher resolution and magnification, which is why electron microscopes could reveal the detailed internal structure of organelles such as mitochondria." },
      { g: 9, marks: 5, q: "Design an investigation to compare the rate of osmosis in two different vegetables, and justify your method.", scheme: ["Cut equal-sized pieces of each vegetable", "Place in the same range of concentrations, same time/temperature", "Measure percentage change in mass", "Repeat and take means", "Justify: controlled variables and % change allow a fair comparison"], answer: "Cut equal-sized pieces of each vegetable and place them in the same range of sugar concentrations for the same time and temperature, then measure the percentage change in mass and repeat for a mean. Controlling these variables and using percentage change makes the comparison between the two vegetables fair and valid." },
    ],

    "2. Organisation": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is a tissue?", scheme: ["A group of similar cells working together / with a similar function"], answer: "A group of similar cells that work together to carry out a function." },
      { g: 4, marks: 1, q: "What is an organ?", scheme: ["A group of tissues working together to perform a function"], answer: "A group of tissues working together to perform a function." },
      { g: 4, marks: 1, q: "What is an organ system?", scheme: ["A group of organs working together"], answer: "A group of organs working together to perform a function." },
      { g: 4, marks: 1, q: "Name the organ that pumps blood around the body.", scheme: ["Heart"], answer: "The heart." },
      { g: 4, marks: 1, q: "Name the tube that carries food from the mouth to the stomach.", scheme: ["Oesophagus"], answer: "The oesophagus." },
      { g: 4, marks: 1, q: "Name the enzyme that breaks down starch.", scheme: ["Amylase (a carbohydrase)"], answer: "Amylase." },
      { g: 4, marks: 1, q: "Where in the body is bile made?", scheme: ["Liver"], answer: "The liver." },
      { g: 4, marks: 1, q: "Name the liquid (straw-coloured) part of blood.", scheme: ["Plasma"], answer: "Plasma." },
      { g: 4, marks: 1, q: "Which blood cells carry oxygen?", scheme: ["Red blood cells"], answer: "Red blood cells." },
      { g: 4, marks: 1, q: "Which blood vessels carry blood away from the heart?", scheme: ["Arteries"], answer: "Arteries." },
      { g: 4, marks: 1, q: "What do enzymes do?", scheme: ["Speed up / catalyse reactions"], answer: "They speed up (catalyse) chemical reactions." },
      { g: 4, marks: 1, q: "Which food group is broken down by protease?", scheme: ["Protein"], answer: "Protein." },
      { g: 4, marks: 1, q: "Name the two upper chambers of the heart.", scheme: ["Atria"], answer: "The atria." },
      { g: 4, marks: 1, q: "Which blood cells help defend against pathogens?", scheme: ["White blood cells"], answer: "White blood cells." },
      { g: 4, marks: 1, q: "Name the tiny blood vessels where exchange happens.", scheme: ["Capillaries"], answer: "Capillaries." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "Define an enzyme.", scheme: ["Biological catalyst", "Speeds up reactions without being used up"], answer: "A biological catalyst that speeds up reactions without being used up." },
      { g: 5, marks: 1, q: "State the products of starch digestion.", scheme: ["Glucose / sugars"], answer: "Glucose (sugars)." },
      { g: 5, marks: 1, q: "State the function of the red blood cell.", scheme: ["Carry oxygen (using haemoglobin)"], answer: "To carry oxygen around the body using haemoglobin." },
      { g: 5, marks: 2, q: "Give two differences between arteries and veins.", scheme: ["Arteries: thick walls / high pressure / no valves", "Veins: thin walls / low pressure / have valves"], answer: "Arteries have thick walls, carry blood at high pressure and have no valves; veins have thin walls, low pressure and valves." },
      { g: 5, marks: 2, q: "State two functions of bile.", scheme: ["Neutralises stomach acid", "Emulsifies fats"], answer: "It neutralises stomach acid and emulsifies fats." },
      { g: 5, marks: 2, q: "Name the four main components of blood.", scheme: ["Red blood cells, white blood cells", "Platelets, plasma"], answer: "Red blood cells, white blood cells, platelets and plasma." },
      { g: 5, marks: 1, q: "State the function of platelets.", scheme: ["Help the blood to clot"], answer: "They help the blood to clot." },
      { g: 5, marks: 2, q: "What is the double circulatory system?", scheme: ["Blood passes through the heart twice per circuit", "One loop to the lungs, one to the body"], answer: "A system where blood passes through the heart twice per circuit — one loop to the lungs and one to the rest of the body." },
      { g: 5, marks: 1, q: "Where is most digested food absorbed?", scheme: ["Small intestine"], answer: "In the small intestine." },
      { g: 5, marks: 1, q: "State what amylase digests and its product.", scheme: ["Starch → glucose (sugars)"], answer: "Amylase digests starch into glucose." },
      { g: 5, marks: 1, q: "Name the protein in red blood cells that binds oxygen.", scheme: ["Haemoglobin"], answer: "Haemoglobin." },
      { g: 5, marks: 1, q: "State the function of the capillaries.", scheme: ["Exchange of substances (O2, CO2, nutrients) with tissues"], answer: "To allow exchange of substances such as oxygen and nutrients with the tissues." },
      { g: 5, marks: 2, q: "Name the three main types of blood vessel.", scheme: ["Arteries, veins", "Capillaries"], answer: "Arteries, veins and capillaries." },
      { g: 5, marks: 1, q: "Which enzyme breaks down fats (lipids)?", scheme: ["Lipase"], answer: "Lipase." },
      { g: 5, marks: 2, q: "State the products of protein and lipid digestion.", scheme: ["Protein → amino acids", "Lipid → fatty acids and glycerol"], answer: "Proteins are digested to amino acids; lipids to fatty acids and glycerol." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why enzymes are specific to one substrate.", scheme: ["Active site is a complementary shape to the substrate", "Only that substrate fits ('lock and key')"], answer: "The active site has a shape complementary to only one substrate, so only that substrate fits — the lock-and-key model." },
      { g: 6, marks: 3, q: "Explain the effect of a high temperature on an enzyme.", scheme: ["Bonds break / enzyme denatures", "Active site changes shape", "Substrate no longer fits → reaction stops"], answer: "A high temperature breaks bonds and denatures the enzyme; the active site changes shape so the substrate no longer fits and the reaction stops." },
      { g: 6, marks: 2, q: "Explain why red blood cells have a biconcave shape and no nucleus.", scheme: ["Biconcave → large surface area for oxygen", "No nucleus → more room for haemoglobin"], answer: "The biconcave shape gives a large surface area to absorb oxygen, and having no nucleus leaves more room for haemoglobin." },
      { g: 6, marks: 3, q: "Explain how the small intestine is adapted for absorption.", scheme: ["Villi give a large surface area", "Thin walls → short diffusion distance", "Good blood supply maintains a gradient"], answer: "It has villi that give a large surface area, thin walls for a short diffusion distance, and a good blood supply to maintain a concentration gradient." },
      { g: 6, marks: 2, q: "Explain why arteries have thick, elastic walls.", scheme: ["To withstand high pressure from the heart", "Elastic to stretch and recoil"], answer: "The walls are thick and elastic to withstand the high pressure of blood pumped from the heart and to stretch and recoil." },
      { g: 6, marks: 2, q: "Explain how bile helps the digestion of fats.", scheme: ["Emulsifies fat into small droplets", "Larger surface area for lipase to work faster"], answer: "Bile emulsifies fat into small droplets, increasing the surface area so lipase can break it down faster." },
      { g: 6, marks: 1, q: "Describe the food test for starch and a positive result.", scheme: ["Add iodine solution; turns blue-black if starch present"], answer: "Add iodine solution — it turns blue-black if starch is present." },
      { g: 6, marks: 2, q: "Describe the test for reducing sugars (glucose).", scheme: ["Add Benedict's solution and heat in a water bath", "Turns brick-red / orange if sugar present"], answer: "Add Benedict's solution and heat it — it turns brick-red if a reducing sugar is present." },
      { g: 6, marks: 2, q: "Describe the test for protein.", scheme: ["Add Biuret solution", "Turns purple/lilac if protein present"], answer: "Add Biuret solution — it turns purple if protein is present." },
      { g: 6, marks: 2, q: "Explain why capillaries have walls that are one cell thick.", scheme: ["Short diffusion distance", "Fast exchange of substances"], answer: "Their walls are one cell thick to give a short diffusion distance for fast exchange of substances." },
      { g: 6, marks: 2, q: "Explain how coronary heart disease develops.", scheme: ["Fatty deposits build up in the coronary arteries", "Narrowing reduces blood/oxygen flow to the heart muscle"], answer: "Fatty deposits build up in the coronary arteries, narrowing them and reducing the flow of oxygenated blood to the heart muscle." },
      { g: 6, marks: 2, q: "Explain how the heart acts as a double pump.", scheme: ["Right side pumps blood to the lungs", "Left side pumps blood to the rest of the body"], answer: "The right side pumps deoxygenated blood to the lungs and the left side pumps oxygenated blood to the rest of the body." },
      { g: 6, marks: 2, q: "Explain the effect of pH on an enzyme.", scheme: ["Each enzyme has an optimum pH", "Too far from it denatures the enzyme / slows the reaction"], answer: "Each enzyme works fastest at its optimum pH; a pH too far from this denatures the enzyme and slows the reaction." },
      { g: 6, marks: 1, q: "State the function of the coronary arteries.", scheme: ["Supply the heart muscle with oxygenated blood"], answer: "They supply the heart muscle with oxygenated blood." },
      { g: 6, marks: 2, q: "Describe the emulsion test for lipids.", scheme: ["Mix sample with ethanol then add water", "Cloudy white layer/emulsion shows lipid"], answer: "Mix the sample with ethanol and add water — a cloudy white emulsion shows a lipid is present." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "Describe the path of food through the digestive system.", scheme: ["Mouth → oesophagus → stomach", "→ small intestine (absorption)", "→ large intestine → rectum"], answer: "Food passes from the mouth down the oesophagus to the stomach, then to the small intestine where it is absorbed, and on to the large intestine." },
      { g: 7, marks: 3, q: "Explain how a stent treats coronary heart disease and give one drawback.", scheme: ["Stent widens/keeps the artery open", "Restores blood and oxygen flow to the heart", "Drawback: risk of a blood clot / further blockage"], answer: "A stent holds the narrowed artery open, restoring blood flow to the heart muscle, but there is a risk of a blood clot forming or the artery blocking again." },
      { g: 7, marks: 3, q: "Explain how statins reduce the risk of heart disease and give one disadvantage.", scheme: ["Lower blood cholesterol / LDL", "Slow the build-up of fatty deposits", "Disadvantage: must be taken long term / side effects"], answer: "Statins lower blood cholesterol, slowing the build-up of fatty deposits in arteries, but they must be taken long term and can have side effects." },
      { g: 7, marks: 4, q: "Describe how you would investigate the effect of pH on the activity of amylase.", scheme: ["Mix amylase, starch and a buffer at a set pH", "Every 30s add a drop to iodine on a tile", "Record time for iodine to stay orange (starch gone)", "Repeat at different pH values; control temperature"], answer: "Mix amylase, starch and a pH buffer, then every 30 seconds place a drop onto iodine until it stays orange, showing the starch has gone. Record the time, repeat at different pH values and control the temperature." },
      { g: 7, marks: 3, q: "Explain how a vein is adapted to return blood to the heart.", scheme: ["Valves prevent backflow", "Wide lumen for low resistance", "Thin walls (blood at low pressure)"], answer: "Veins have valves to prevent backflow, a wide lumen to ease flow, and thin walls because the blood is at low pressure." },
      { g: 7, marks: 4, q: "Explain how the alveoli are adapted for gas exchange.", scheme: ["Large surface area (many alveoli)", "Thin walls / short diffusion distance", "Moist surface", "Good blood supply maintains the gradient"], answer: "The alveoli give a large surface area, have thin walls for a short diffusion distance, a moist surface, and a good blood supply to maintain a steep concentration gradient." },
      { g: 7, marks: 3, q: "Explain the lock-and-key model of enzyme action.", scheme: ["Substrate binds to the complementary active site", "Forms an enzyme-substrate complex; reaction occurs", "Products released; enzyme is reused"], answer: "The substrate binds to the enzyme's complementary active site, forming a complex where the reaction happens; the products are released and the enzyme is used again." },
      { g: 7, marks: 3, q: "Explain how the structure of an artery relates to its function.", scheme: ["Thick muscular and elastic wall", "Withstands and maintains high pressure", "Narrow lumen keeps pressure high"], answer: "Arteries have a thick muscular, elastic wall to withstand and maintain the high pressure of blood, and a narrow lumen helps keep the pressure high." },
      { g: 7, marks: 3, q: "Compare mechanical and biological (donor) heart valves.", scheme: ["Mechanical last longer but need anticoagulant drugs", "Biological don't need drugs but may wear out", "Both restore correct blood flow"], answer: "Mechanical valves last longer but the patient must take anticoagulants; biological valves don't need drugs but wear out sooner — both stop blood flowing the wrong way." },
      { g: 7, marks: 3, q: "Name four risk factors for coronary heart disease and briefly link one to CHD.", scheme: ["Poor diet, smoking, lack of exercise, high blood pressure (any 4)", "e.g. a high-fat diet raises cholesterol → fatty deposits"], answer: "Poor diet, smoking, lack of exercise and high blood pressure; for example a high-fat diet raises cholesterol, leading to fatty deposits in the arteries." },
      { g: 7, marks: 3, q: "Explain the effect of increasing substrate concentration on the rate of an enzyme reaction.", scheme: ["Rate increases at first (more collisions)", "Then levels off/plateaus", "All active sites occupied / enzyme saturated"], answer: "Increasing substrate concentration increases the rate at first as there are more collisions, then the rate plateaus when all the enzyme active sites are occupied." },
      { g: 7, marks: 3, q: "Explain why an artificial heart may be used instead of a donor heart.", scheme: ["No donor needed / avoids waiting list", "Less likely to be rejected by the immune system", "Can keep a patient alive until a transplant"], answer: "An artificial heart avoids the shortage of donors, is less likely to be rejected, and can keep a patient alive while they wait for a transplant." },
      { g: 7, marks: 2, q: "Explain why pepsin (a protease) works in the stomach even though it is acidic.", scheme: ["Pepsin has a low optimum pH", "So the acidic conditions suit it"], answer: "Pepsin has a low optimum pH, so the acidic conditions of the stomach are where it works best." },
      { g: 7, marks: 3, q: "Explain how blood, blood vessels and the heart work together to supply the body.", scheme: ["Heart pumps blood through vessels", "Arteries carry blood at high pressure to organs", "Capillaries exchange substances; veins return blood"], answer: "The heart pumps blood into arteries which carry it at high pressure to organs, where capillaries exchange substances, and veins return the blood to the heart." },
      { g: 7, marks: 2, q: "Explain why food is chewed and mixed with digestive juices before absorption.", scheme: ["Increases surface area / breaks large molecules down", "So soluble molecules can be absorbed into the blood"], answer: "Chewing and enzymes break food into small, soluble molecules with a larger surface area, so they can be absorbed into the blood." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain fully why the rate of an enzyme reaction rises and then falls as temperature increases.", scheme: ["As temperature rises, particles have more energy → more collisions", "Rate increases up to the optimum", "Above the optimum, bonds break and the enzyme denatures", "Active site changes shape → substrate no longer fits → rate falls"], answer: "As temperature increases, particles move faster and collide more often, so the rate rises to the optimum. Above the optimum, bonds break and the enzyme denatures, changing the active site so the substrate no longer fits and the rate falls." },
      { g: 8, marks: 4, q: "Evaluate the use of stents compared with statins to treat coronary heart disease.", scheme: ["Stents: immediate effect, keep artery open, but surgical/clot risk", "Statins: long-term prevention, lower cholesterol, but side effects/daily use", "Stents treat a blockage; statins reduce future risk", "Judgement based on the patient's situation"], answer: "Stents open a blocked artery immediately but involve surgery and a risk of clots, while statins prevent further build-up over the long term but must be taken daily and can have side effects. Stents treat an existing blockage whereas statins reduce future risk, so the best choice depends on the patient." },
      { g: 8, marks: 4, q: "Explain how the small intestine is adapted to absorb the products of digestion efficiently.", scheme: ["Very long / folded → large surface area", "Villi and microvilli increase surface area further", "Thin (one-cell) walls → short diffusion distance", "Rich blood supply maintains the concentration gradient"], answer: "The small intestine is long and folded with villi and microvilli, giving a very large surface area. Its thin walls give a short diffusion distance, and a rich blood supply maintains a steep concentration gradient for fast absorption." },
      { g: 8, marks: 3, q: "Explain the difference between a benign and a malignant tumour.", scheme: ["Both are uncontrolled cell division", "Benign stays in one place / does not spread", "Malignant invades tissues and spreads (metastasis) in the blood"], answer: "Both result from uncontrolled cell division. A benign tumour stays in one place, whereas a malignant tumour invades other tissues and spreads through the blood (metastasis)." },
      { g: 8, marks: 4, q: "Explain how the leaf is adapted for photosynthesis and gas exchange, naming its tissues.", scheme: ["Palisade mesophyll: many chloroplasts near the top for light", "Spongy mesophyll: air spaces for gas exchange", "Stomata and guard cells control gas exchange/water loss", "Xylem and phloem transport water and sugars"], answer: "The palisade layer has many chloroplasts near the top to absorb light, the spongy mesophyll has air spaces for gas exchange, stomata with guard cells control gas exchange and water loss, and xylem and phloem transport water and sugars." },
      { g: 8, marks: 4, q: "Explain what transpiration is and how four factors affect its rate.", scheme: ["Loss of water vapour from the leaves (via stomata)", "Higher temperature → faster (more evaporation)", "More wind and lower humidity → faster", "More light → stomata open → faster"], answer: "Transpiration is the loss of water vapour from the leaves through the stomata. Higher temperature, more wind, lower humidity and brighter light all increase the rate because they increase evaporation or open the stomata." },
      { g: 8, marks: 3, q: "Explain how guard cells control water loss from a leaf.", scheme: ["In light guard cells become turgid and open the stomata", "Allows CO2 in for photosynthesis", "In dry conditions they close the stomata to reduce water loss"], answer: "In the light the guard cells become turgid and open the stomata to let CO2 in for photosynthesis, but in dry conditions they close to reduce water loss." },
      { g: 8, marks: 3, q: "Explain the difference between transpiration and translocation.", scheme: ["Transpiration: water moves up in the xylem (one direction)", "Translocation: sugars move in the phloem", "Translocation can move sugars in both directions"], answer: "Transpiration is the movement of water up the plant in the xylem, while translocation is the movement of dissolved sugars in the phloem, which can travel in both directions." },
      { g: 8, marks: 4, q: "Evaluate the advantages and disadvantages of a heart transplant versus an artificial heart.", scheme: ["Transplant: works fully but donor shortage and rejection risk", "Artificial: always available, no rejection, but clot risk / needs a power source", "Transplant needs immunosuppressants", "Judgement"], answer: "A transplant restores full function but relies on scarce donors, risks rejection and needs immunosuppressant drugs. An artificial heart is always available and isn't rejected but risks blood clots and needs a power source, so a transplant is usually preferred where a donor is available." },
      { g: 8, marks: 3, q: "Explain how you could make an investigation into enzyme activity valid and repeatable.", scheme: ["Control variables (temperature, volumes, concentrations)", "Repeat readings and take a mean", "Use the same method/timing each time"], answer: "Keep variables such as temperature, volumes and concentrations the same, use the same method and timing, and repeat each reading to take a mean." },
      { g: 8, marks: 3, q: "Explain why the double circulatory system is more efficient than a single one.", scheme: ["Blood is re-pressurised by the heart after the lungs", "So it reaches the body at high pressure/quickly", "Oxygenated and deoxygenated blood are kept separate"], answer: "After passing through the lungs the blood returns to the heart to be pumped again at high pressure, so it reaches the body quickly, and oxygenated and deoxygenated blood are kept separate for efficiency." },
      { g: 8, marks: 3, q: "Explain how lifestyle factors increase the risk of non-communicable diseases.", scheme: ["Poor diet/obesity → type 2 diabetes, heart disease", "Smoking → lung disease/cancer", "Alcohol → liver disease"], answer: "A poor diet and obesity raise the risk of type 2 diabetes and heart disease, smoking increases the risk of lung disease and cancer, and excess alcohol damages the liver." },
      { g: 8, marks: 3, q: "Explain why exercise causes heart rate to increase.", scheme: ["Muscles respire more / need more oxygen and glucose", "And need to remove more carbon dioxide", "Faster heart rate delivers blood more quickly"], answer: "During exercise the muscles respire more and need more oxygen and glucose and to remove more carbon dioxide, so the heart beats faster to deliver blood more quickly." },
      { g: 8, marks: 3, q: "Explain how a mineral deficiency affects plant growth (nitrate and magnesium).", scheme: ["Nitrate needed for proteins/amino acids → deficiency stunts growth", "Magnesium needed for chlorophyll → deficiency causes yellow leaves (chlorosis)"], answer: "Nitrate ions are needed to make proteins, so a deficiency stunts growth, and magnesium ions are needed for chlorophyll, so a deficiency causes yellowing of the leaves (chlorosis)." },
      { g: 8, marks: 3, q: "Analyse why an enzyme reaction stops completely above a certain temperature but only slows at low temperature.", scheme: ["Low temperature: less energy → fewer collisions → slower but reversible", "High temperature: enzyme denatures permanently", "Active site shape permanently changed"], answer: "At low temperature there is less energy so fewer collisions and a slower rate, but this is reversible. At high temperature the enzyme denatures permanently as its active site changes shape, so the reaction stops for good." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain fully how a meal is digested and absorbed, naming the enzymes, their products and where they act.", scheme: ["Carbohydrase/amylase (mouth, small intestine): starch → glucose", "Protease (stomach, small intestine): protein → amino acids", "Lipase (small intestine): lipids → fatty acids and glycerol", "Bile emulsifies fat and neutralises acid", "Small, soluble molecules absorbed by villi", "Into the blood/lymph"], answer: "Amylase in the mouth and small intestine digests starch to glucose; protease in the stomach and small intestine digests protein to amino acids; lipase in the small intestine digests lipids to fatty acids and glycerol, helped by bile which emulsifies fat and neutralises stomach acid. The small, soluble products are then absorbed through the villi into the blood." },
      { g: 9, marks: 6, q: "Evaluate the different treatments available for cardiovascular disease.", scheme: ["Stents: open arteries, quick, but surgical/clot risk", "Statins: lower cholesterol long term, side effects", "Transplant: full function, donor shortage, rejection", "Artificial heart: available, no rejection, clot risk/power", "Lifestyle change: cheap, no side effects, relies on the patient", "Justified conclusion weighing risks and benefits"], answer: "Stents quickly open blocked arteries but involve surgery and clot risk; statins lower cholesterol long term but have side effects; transplants restore full function but donors are scarce and rejection is a risk; artificial hearts are available but risk clots. Lifestyle changes are cheapest and safest but rely on the patient. The best treatment depends on how severe the disease is and the patient's circumstances." },
      { g: 9, marks: 6, q: "Explain fully how temperature and pH affect enzyme-controlled reactions using the lock-and-key model.", scheme: ["Substrate fits the complementary active site (lock and key)", "Rising temperature increases collisions → faster rate to the optimum", "Above the optimum the enzyme denatures", "Each enzyme has an optimum pH", "Away from optimum pH bonds break, active site changes shape", "Substrate no longer fits → rate falls"], answer: "The substrate fits the enzyme's complementary active site like a key in a lock. Raising the temperature increases collisions and the rate up to the optimum, but above it the enzyme denatures. Each enzyme also has an optimum pH; moving away from it breaks bonds and changes the active site's shape so the substrate no longer fits and the rate falls." },
      { g: 9, marks: 6, q: "Explain how exchange surfaces in the body (alveoli, villi and root hair cells) are adapted, using surface area, thickness and gradients.", scheme: ["All have a large surface area", "All have thin walls / short diffusion distance", "Good blood supply / transport to maintain the gradient", "Alveoli: moist, many air sacs for gases", "Villi: absorb digested food", "Root hair: absorb water and minerals"], answer: "Alveoli, villi and root hair cells all have a large surface area and thin walls giving a short diffusion distance, with a good blood supply or transport system to maintain a steep concentration gradient. Alveoli exchange gases, villi absorb digested food, and root hair cells absorb water and minerals." },
      { g: 9, marks: 5, q: "Design an experiment to find the optimum pH of a protease enzyme and justify your method.", scheme: ["Use protease with a protein (e.g. milk/egg) at a range of pH values", "Buffers to set pH; control temperature and volumes", "Measure time for the protein to be broken down / clear", "Repeat and take a mean", "Justify: controlled variables and repeats give a fair, reliable result"], answer: "React protease with a protein at a range of pH values set by buffers, keeping temperature and volumes constant, and time how long it takes for the protein to be broken down. Repeat each pH and take a mean. Controlling the variables and repeating makes the comparison fair and the optimum pH reliable." },
      { g: 9, marks: 6, q: "Explain fully the causes, effects and prevention of coronary heart disease.", scheme: ["Cause: fatty deposits narrow the coronary arteries", "Less oxygen to the heart muscle → chest pain / heart attack", "Risk factors: diet, smoking, lack of exercise, high blood pressure", "Prevention: healthy diet, exercise, not smoking", "Treatment: stents, statins, surgery", "Linked reasoning throughout"], answer: "Coronary heart disease is caused by fatty deposits narrowing the coronary arteries, reducing oxygen to the heart muscle and causing chest pain or a heart attack. Risk factors include a poor diet, smoking, lack of exercise and high blood pressure, so it can be prevented by a healthy diet, exercise and not smoking, and treated with stents, statins or surgery." },
      { g: 9, marks: 6, q: "Explain how water and dissolved sugars are transported in a plant, and how transpiration is measured.", scheme: ["Water absorbed by root hair cells → xylem", "Xylem carries water up (transpiration stream)", "Phloem translocates sugars (both directions)", "Transpiration = loss of water vapour from leaves", "Measured with a potometer (uptake of water)", "Faster in warm, dry, windy, bright conditions"], answer: "Water is absorbed by root hair cells and carried up the xylem in the transpiration stream, while sugars are translocated in the phloem in both directions. Transpiration is the loss of water vapour from the leaves and can be measured with a potometer, which measures water uptake; it is faster in warm, dry, windy and bright conditions." },
      { g: 9, marks: 5, q: "Explain how four environmental factors interact to affect the rate of transpiration.", scheme: ["Temperature: warmer → faster evaporation", "Humidity: drier air → steeper gradient → faster", "Wind: removes water vapour → steeper gradient → faster", "Light: opens stomata → faster", "Factors combine (e.g. warm, dry, windy day = fastest)"], answer: "Higher temperature speeds evaporation, low humidity and wind keep the concentration gradient steep by removing water vapour, and bright light opens the stomata. These combine, so a warm, dry, windy and bright day gives the fastest transpiration." },
      { g: 9, marks: 5, q: "Explain how a change in the shape of an enzyme's active site (from a mutation) could stop it working.", scheme: ["Active site shape is determined by the enzyme's structure", "A mutation changes the amino acid sequence/structure", "Active site shape changes", "Substrate no longer complementary / can't bind", "No enzyme-substrate complex → reaction not catalysed"], answer: "A mutation changes the enzyme's amino acid sequence and therefore the shape of its active site. If the active site is no longer complementary to the substrate, the substrate can't bind to form an enzyme-substrate complex, so the reaction is no longer catalysed." },
      { g: 9, marks: 6, q: "Explain how the heart, blood vessels and blood work together to deliver oxygen and glucose to respiring cells and remove waste.", scheme: ["Heart pumps blood in a double circuit", "Oxygenated blood leaves the left side to the body via arteries", "Capillaries allow exchange with cells (O2, glucose in; CO2 out)", "Red blood cells carry oxygen; plasma carries glucose/CO2", "Deoxygenated blood returns via veins to the heart then lungs"], answer: "The heart pumps blood around a double circuit. Oxygenated blood leaves the left side through arteries to the body, where capillaries allow oxygen and glucose to pass into cells and carbon dioxide to leave. Red blood cells carry the oxygen and plasma carries glucose and carbon dioxide, and deoxygenated blood returns through the veins to the heart and lungs." },
      { g: 9, marks: 5, q: "Analyse why doctors consider several risk factors together, not just one, when assessing heart disease risk.", scheme: ["Risk factors interact / add up", "One factor alone may be low risk", "Several together greatly increase risk", "Some factors are lifestyle (changeable), some genetic", "Better prediction from combining them"], answer: "Risk factors such as diet, smoking, exercise and genetics interact and add up, so one alone may pose little risk but several together greatly increase it. Some are lifestyle factors that can be changed and some are genetic, so combining them gives a more accurate prediction of overall risk." },
      { g: 9, marks: 6, q: "Explain how the structures of the artery, vein and capillary each relate to their functions.", scheme: ["Artery: thick elastic muscular wall, narrow lumen → withstands high pressure", "Vein: thin wall, wide lumen, valves → low-pressure return, prevents backflow", "Capillary: one-cell-thick wall → short diffusion distance for exchange", "Each linked to pressure/role"], answer: "Arteries have thick, elastic, muscular walls and a narrow lumen to withstand and maintain high pressure from the heart. Veins have thin walls, a wide lumen and valves to return blood at low pressure without backflow. Capillaries have walls one cell thick, giving a short diffusion distance for the exchange of substances with cells." },
      { g: 9, marks: 5, q: "Evaluate whether lifestyle change or medication is the better approach to reducing cardiovascular disease.", scheme: ["Lifestyle: cheap, no side effects, prevents many diseases, but relies on the patient", "Medication (statins): reliable cholesterol reduction, but side effects/cost/long term", "Lifestyle tackles the cause; medication manages risk", "Often used together", "Justified conclusion"], answer: "Lifestyle change is cheap, has no side effects and prevents several diseases, but relies on the patient sticking to it. Medication such as statins reliably lowers cholesterol but has side effects and costs money long term. Lifestyle tackles the cause while medication manages risk, so they are often best combined, with lifestyle change the priority where possible." },
      { g: 9, marks: 6, q: "Explain how enzymes, bile and the structure of the gut all contribute to efficient digestion and absorption.", scheme: ["Enzymes break large molecules into small soluble ones", "Amylase, protease, lipase act on specific foods", "Bile emulsifies fat (larger SA) and neutralises acid for enzymes", "Gut is muscular → mixes and moves food", "Villi give large SA, thin walls, blood supply for absorption"], answer: "Enzymes such as amylase, protease and lipase break large molecules into small soluble ones, while bile emulsifies fat to increase its surface area and neutralises stomach acid so enzymes in the small intestine work well. The muscular gut mixes and moves the food, and the villi provide a large surface area, thin walls and a blood supply for efficient absorption." },
      { g: 9, marks: 5, q: "Explain, using the idea of concentration gradients, how oxygen moves from an alveolus into the blood and carbon dioxide moves out.", scheme: ["Oxygen higher in the alveolus than in the blood", "Oxygen diffuses down its gradient into the blood/red blood cells", "Carbon dioxide higher in the blood than the alveolus", "CO2 diffuses out into the alveolus", "Breathing and blood flow maintain the gradients"], answer: "Oxygen is at a higher concentration in the alveolus than in the blood, so it diffuses down its gradient into the red blood cells, while carbon dioxide is higher in the blood and diffuses out into the alveolus. Breathing and blood flow keep replacing the air and blood, maintaining steep gradients for fast exchange." },
    ],

    "3. Infection and response": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is a pathogen?", scheme: ["A microorganism that causes (communicable) disease"], answer: "A microorganism that causes disease." },
      { g: 4, marks: 1, q: "Name the four types of pathogen.", scheme: ["Bacteria, viruses, fungi, protists"], answer: "Bacteria, viruses, fungi and protists." },
      { g: 4, marks: 1, q: "What is a communicable disease?", scheme: ["A disease that can spread between organisms/people"], answer: "A disease that can be spread from one organism to another." },
      { g: 4, marks: 1, q: "What type of pathogen causes malaria?", scheme: ["A protist"], answer: "A protist." },
      { g: 4, marks: 1, q: "Name a disease caused by a virus.", scheme: ["Measles / HIV / tobacco mosaic virus (any one)"], answer: "Measles (or HIV, or tobacco mosaic virus)." },
      { g: 4, marks: 1, q: "Name a disease caused by bacteria.", scheme: ["Salmonella / gonorrhoea (any one)"], answer: "Salmonella (or gonorrhoea)." },
      { g: 4, marks: 1, q: "Which cells in the body produce antibodies?", scheme: ["White blood cells (lymphocytes)"], answer: "White blood cells (lymphocytes)." },
      { g: 4, marks: 1, q: "What type of medicine kills bacteria?", scheme: ["Antibiotics"], answer: "Antibiotics." },
      { g: 4, marks: 1, q: "Do antibiotics kill viruses?", scheme: ["No"], answer: "No, antibiotics do not kill viruses." },
      { g: 4, marks: 1, q: "What do vaccines contain?", scheme: ["A small/dead/inactive form of a pathogen (or its antigen)"], answer: "A small, dead or inactive form of a pathogen (its antigen)." },
      { g: 4, marks: 1, q: "Name one way pathogens can spread.", scheme: ["Air/droplets, water, direct contact, vectors (any one)"], answer: "Through the air (droplets), water, direct contact or vectors." },
      { g: 4, marks: 1, q: "What is the body's outer physical barrier to pathogens?", scheme: ["The skin"], answer: "The skin." },
      { g: 4, marks: 1, q: "What relieves symptoms but does not kill the pathogen?", scheme: ["Painkillers"], answer: "Painkillers." },
      { g: 4, marks: 1, q: "Which insect spreads malaria?", scheme: ["The mosquito"], answer: "The mosquito." },
      { g: 4, marks: 1, q: "Name the virus that causes a mosaic pattern on plant leaves.", scheme: ["Tobacco mosaic virus (TMV)"], answer: "Tobacco mosaic virus (TMV)." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "Describe how bacteria can make us ill.", scheme: ["Reproduce rapidly (in the body)", "Produce toxins that damage tissues"], answer: "Bacteria reproduce rapidly and produce toxins that damage cells and tissues." },
      { g: 5, marks: 2, q: "Describe how viruses make us ill.", scheme: ["Reproduce inside body cells", "The cell bursts / is damaged when they are released"], answer: "Viruses reproduce inside body cells, which are damaged or burst when the new viruses are released." },
      { g: 5, marks: 2, q: "State two ways white blood cells defend the body.", scheme: ["Engulf pathogens (phagocytosis)", "Produce antibodies / antitoxins"], answer: "They engulf pathogens (phagocytosis) and produce antibodies and antitoxins." },
      { g: 5, marks: 2, q: "State two non-specific (physical or chemical) defences of the body.", scheme: ["Any two: skin, mucus, cilia, stomach acid, tears/lysozyme"], answer: "The skin, and mucus and cilia in the airways (also stomach acid and tears)." },
      { g: 5, marks: 2, q: "Describe how vaccination protects against a disease.", scheme: ["A dead/inactive pathogen (antigen) is introduced", "White blood cells make antibodies and memory cells remain"], answer: "A dead or inactive form of the pathogen is introduced, and white blood cells make antibodies against it, leaving memory cells behind." },
      { g: 5, marks: 1, q: "State how measles is spread.", scheme: ["By droplets / inhalation (coughs and sneezes)"], answer: "By breathing in droplets from an infected person's coughs and sneezes." },
      { g: 5, marks: 1, q: "State how HIV is spread.", scheme: ["Exchange of body fluids (e.g. blood, sexual contact)"], answer: "Through the exchange of body fluids, such as blood or during sexual contact." },
      { g: 5, marks: 2, q: "State how salmonella is spread and one symptom.", scheme: ["Spread by eating contaminated food", "Symptoms: fever, cramps, vomiting or diarrhoea"], answer: "It is spread by eating contaminated food and causes fever, cramps, vomiting or diarrhoea." },
      { g: 5, marks: 1, q: "Define an antibody.", scheme: ["A protein made by white blood cells that binds to a specific antigen"], answer: "A protein made by white blood cells that binds to a specific antigen." },
      { g: 5, marks: 1, q: "Define an antigen.", scheme: ["A marker/molecule on the surface of a pathogen"], answer: "A unique marker molecule on the surface of a pathogen." },
      { g: 5, marks: 1, q: "State how TMV reduces a plant's growth.", scheme: ["Discolours leaves (mosaic pattern) → less photosynthesis"], answer: "It discolours the leaves in a mosaic pattern, so the plant photosynthesises less." },
      { g: 5, marks: 2, q: "State two ways to reduce the spread of communicable disease.", scheme: ["Any two: hygiene/handwashing, isolation, vaccination, vector control"], answer: "Good hygiene such as handwashing, isolating the infected, vaccination, and controlling vectors." },
      { g: 5, marks: 2, q: "State the difference between what antibiotics and painkillers do.", scheme: ["Antibiotics kill bacteria", "Painkillers only relieve symptoms"], answer: "Antibiotics kill bacteria, whereas painkillers only relieve symptoms." },
      { g: 5, marks: 1, q: "State how the stomach helps defend against pathogens.", scheme: ["Produces hydrochloric acid that kills pathogens"], answer: "It produces hydrochloric acid that kills many pathogens in food." },
      { g: 5, marks: 1, q: "Name the fungal plant disease that causes purple/black spots on leaves.", scheme: ["Rose black spot"], answer: "Rose black spot." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain how phagocytosis defends the body.", scheme: ["A white blood cell surrounds/engulfs the pathogen", "It digests/destroys it with enzymes"], answer: "A white blood cell engulfs the pathogen and digests it using enzymes, destroying it." },
      { g: 6, marks: 2, q: "Explain how antibodies destroy pathogens.", scheme: ["Bind to the specific antigen on the pathogen", "Clump pathogens together / mark them for destruction"], answer: "Antibodies bind to the specific antigens on a pathogen, clumping them together and marking them to be destroyed." },
      { g: 6, marks: 2, q: "Explain why antibiotics do not work against viral diseases.", scheme: ["Viruses reproduce inside the body's cells", "Hard to kill them without damaging the cells"], answer: "Viruses live and reproduce inside the body's own cells, so it is difficult to destroy them without harming the cells." },
      { g: 6, marks: 3, q: "Explain how vaccination makes you immune to a disease.", scheme: ["The antigen triggers white blood cells to make antibodies", "Memory cells remain", "On reinfection antibodies are made quickly, before you fall ill"], answer: "The vaccine's antigen triggers white blood cells to make antibodies and memory cells. If the real pathogen infects you later, the memory cells make antibodies quickly, destroying it before you become ill." },
      { g: 6, marks: 2, q: "Explain what is meant by herd immunity.", scheme: ["If a large proportion of the population is vaccinated/immune", "The pathogen cannot spread easily, protecting the unvaccinated"], answer: "If enough of the population is vaccinated, the pathogen cannot spread easily, which protects even those who are not vaccinated." },
      { g: 6, marks: 3, q: "Explain how antibiotic-resistant bacteria arise.", scheme: ["A random mutation makes some bacteria resistant", "These survive when antibiotics are used", "They reproduce and pass on the resistance (natural selection)"], answer: "A random mutation makes some bacteria resistant to the antibiotic. When the antibiotic is used, the resistant bacteria survive and reproduce, passing on the resistance — natural selection." },
      { g: 6, marks: 2, q: "Explain two ways of reducing the spread of malaria.", scheme: ["Mosquito nets / insecticides to stop bites", "Remove standing water to stop mosquitoes breeding"], answer: "Use mosquito nets and insecticides to prevent bites, and remove standing water so mosquitoes cannot breed." },
      { g: 6, marks: 2, q: "Explain the role of memory cells after an infection.", scheme: ["Remain in the body after the infection", "Respond faster and stronger to the same pathogen next time"], answer: "Memory cells stay in the body and respond faster and more strongly if the same pathogen infects you again." },
      { g: 6, marks: 2, q: "Explain how antitoxins help fight bacterial infection.", scheme: ["Produced by white blood cells", "Neutralise the toxins produced by bacteria"], answer: "White blood cells produce antitoxins that neutralise the harmful toxins released by bacteria." },
      { g: 6, marks: 2, q: "Explain why it is important to finish a full course of antibiotics.", scheme: ["Ensures all the bacteria are killed", "Reduces the chance of resistance developing"], answer: "Finishing the course kills all the bacteria, which reduces the chance that resistant bacteria survive and spread." },
      { g: 6, marks: 2, q: "Explain how the skin, mucus and cilia work together to defend the airways.", scheme: ["Mucus traps pathogens/particles", "Cilia waft the mucus away (out of the airways)"], answer: "Mucus in the airways traps pathogens, and cilia waft the mucus (and trapped pathogens) up and out of the lungs." },
      { g: 6, marks: 2, q: "Explain how vaccinating poultry can reduce salmonella in humans.", scheme: ["Reduces the number of bacteria in the birds", "So less salmonella enters the food chain"], answer: "Vaccinating poultry reduces the salmonella bacteria they carry, so less of it enters the human food chain." },
      { g: 6, marks: 2, q: "Explain why measles can be dangerous if untreated.", scheme: ["Can lead to serious complications", "e.g. pneumonia or brain damage"], answer: "Measles can lead to serious complications such as pneumonia or brain damage, so it can be dangerous if untreated." },
      { g: 6, marks: 2, q: "Explain how gonorrhoea can be controlled.", scheme: ["Treat with antibiotics (e.g. penicillin)", "Use barrier contraception (condoms)"], answer: "It is treated with antibiotics and its spread is reduced by using barrier contraception such as condoms." },
      { g: 6, marks: 2, q: "Explain how rose black spot affects a plant and how it spreads.", scheme: ["Fungus reduces leaf area → less photosynthesis/growth", "Spread in water/air; treated with fungicides / removing leaves"], answer: "The fungus reduces the leaf area for photosynthesis, slowing growth; it spreads in water and air and is treated with fungicides or by removing affected leaves." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 3, q: "Describe the stages a new drug goes through before it can be prescribed.", scheme: ["Preclinical testing on cells and tissues, then animals", "Clinical trials on healthy volunteers (safety/dose)", "Then on patients (efficacy)"], answer: "A new drug is first tested on cells, tissues and animals, then in clinical trials on healthy volunteers to check safety and dose, and finally on patients to check that it works." },
      { g: 7, marks: 3, q: "Explain what is tested in clinical trials and why low doses are used at first.", scheme: ["Tests toxicity (safety), efficacy and dose", "Low doses first to reduce the risk of harm"], answer: "Clinical trials test the drug's safety (toxicity), whether it works (efficacy) and the best dose; very low doses are used first to reduce the risk of harming volunteers." },
      { g: 7, marks: 3, q: "Explain what a double-blind trial with a placebo is and why it is used.", scheme: ["Some patients get the drug, others a placebo", "Neither the patient nor the doctor knows which", "Reduces bias in the results"], answer: "In a double-blind trial some patients receive the drug and others a placebo, and neither the patient nor the doctor knows which, so the results are not affected by bias." },
      { g: 7, marks: 4, q: "Describe how monoclonal antibodies are produced.", scheme: ["A mouse is injected with an antigen to make lymphocytes", "Lymphocytes are fused with a tumour cell", "Forming a hybridoma that divides quickly", "The hybridoma clones make one specific antibody"], answer: "A mouse is injected with an antigen so it makes lymphocytes; these are fused with fast-dividing tumour cells to form hybridomas, which are cloned to produce large amounts of a single specific antibody." },
      { g: 7, marks: 3, q: "Explain three uses of monoclonal antibodies.", scheme: ["Pregnancy tests (detect a hormone)", "Detecting/diagnosing disease (e.g. cancer)", "Delivering drugs to specific cells"], answer: "They are used in pregnancy tests to detect a hormone, to detect or diagnose diseases such as cancer, and to carry drugs directly to specific cells." },
      { g: 7, marks: 3, q: "Explain how antibiotic resistance in bacteria such as MRSA develops (natural selection).", scheme: ["Mutation gives some bacteria resistance", "Antibiotics kill non-resistant bacteria; resistant survive", "They reproduce and the resistant population spreads"], answer: "A mutation makes some bacteria resistant; when antibiotics are used the non-resistant bacteria die but the resistant ones survive, reproduce and spread, so the resistant strain becomes common." },
      { g: 7, marks: 3, q: "Explain how the spread of antibiotic resistance can be slowed.", scheme: ["Doctors avoid over-prescribing antibiotics", "Not using them for viral/mild infections", "Patients complete the full course"], answer: "Doctors should avoid prescribing antibiotics unnecessarily or for viral infections, and patients should always complete the full course, so fewer resistant bacteria survive." },
      { g: 7, marks: 3, q: "Explain how vaccinating a large proportion of a population can prevent an epidemic.", scheme: ["Most people are immune", "The pathogen cannot spread easily between people", "Even unvaccinated people are protected (herd immunity)"], answer: "If most people are vaccinated and immune, the pathogen cannot spread easily from person to person, so an epidemic is prevented and even unvaccinated people are protected." },
      { g: 7, marks: 3, q: "Describe three types of plant defence against disease.", scheme: ["Physical: waxy cuticle / cellulose cell walls / bark", "Chemical: antibacterial or poisonous chemicals", "Mechanical: thorns, hairs, drooping/curling leaves"], answer: "Plants defend themselves physically with a waxy cuticle and cellulose walls, chemically by making antibacterial or poisonous substances, and mechanically with thorns, hairs or leaves that droop when touched." },
      { g: 7, marks: 3, q: "Explain how you would identify the cause of a diseased plant.", scheme: ["Observe signs (spots, discolouration, growths, stunting)", "Use a gardening manual/website or a testing kit", "Or send to a lab to identify the pathogen"], answer: "You would look at the signs such as spots, discolouration or stunted growth, compare them using a gardening manual or a testing kit, or send a sample to a laboratory to identify the pathogen." },
      { g: 7, marks: 2, q: "Explain how a nitrate deficiency and a magnesium deficiency affect a plant.", scheme: ["Nitrate: needed for proteins → stunted growth", "Magnesium: needed for chlorophyll → yellow leaves (chlorosis)"], answer: "Without nitrate the plant cannot make enough protein, so growth is stunted; without magnesium it cannot make chlorophyll, so the leaves turn yellow." },
      { g: 7, marks: 3, q: "Explain why aseptic technique is used when culturing microorganisms.", scheme: ["Prevents contamination by unwanted microbes from the air/surroundings", "Keeps the culture pure/valid", "Protects the scientist from harmful microbes"], answer: "Aseptic technique prevents unwanted microbes from the air or surroundings contaminating the culture, keeping it pure and protecting the scientist." },
      { g: 7, marks: 2, q: "A single bacterium divides every 30 minutes. How many are there after 3 hours? Show your working.", scheme: ["3 hours = 6 divisions", "2^6 = 64"], answer: "In 3 hours there are 6 divisions, so 2^6 = 64 bacteria." },
      { g: 7, marks: 2, q: "Explain why school Petri dish cultures are incubated at 25°C, not 37°C.", scheme: ["Prevents growth of harmful human pathogens", "(These grow best at body temperature, 37°C)"], answer: "Incubating at 25°C rather than body temperature reduces the growth of pathogens that could harm humans." },
      { g: 7, marks: 3, q: "Explain how a pregnancy test uses monoclonal antibodies.", scheme: ["Antibodies bind to the hormone (HCG) in urine", "The hormone-antibody complex moves along the strip", "Binds and shows a coloured line if the hormone is present"], answer: "The test contains monoclonal antibodies that bind to the pregnancy hormone in urine; the complex moves along the strip and binds to a line of antibodies, giving a coloured line if the hormone is present." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain fully how the immune system responds when a pathogen enters the body.", scheme: ["White blood cells engulf pathogens (phagocytosis)", "Some produce antibodies specific to the antigen", "Some produce antitoxins to neutralise toxins", "Memory cells remain for a faster future response"], answer: "White blood cells engulf and digest pathogens by phagocytosis, others produce antibodies specific to the pathogen's antigens, and some produce antitoxins to neutralise toxins. Memory cells are also made so the body responds faster if the pathogen returns." },
      { g: 8, marks: 4, q: "Evaluate the benefits and risks of vaccination.", scheme: ["Benefits: prevents disease and epidemics; herd immunity", "Has controlled/eradicated diseases (e.g. smallpox)", "Risks: rare side effects", "Not always 100% effective / ethical concerns", "Judgement that benefits usually outweigh risks"], answer: "Vaccination prevents disease and epidemics through herd immunity and has controlled diseases such as smallpox. There are rare side effects and it is not always fully effective, but for most people the benefits of preventing serious disease outweigh the small risks." },
      { g: 8, marks: 4, q: "Explain how monoclonal antibodies can be used to treat cancer.", scheme: ["Made to bind to a specific antigen on cancer cells", "Can carry a drug/radioactive substance/toxin", "Delivered directly to the cancer cells", "Kills cancer cells without harming normal cells as much"], answer: "Monoclonal antibodies are made to bind to a specific antigen found on cancer cells and can carry a drug, toxin or radioactive substance directly to them, killing the cancer cells while causing less harm to normal cells." },
      { g: 8, marks: 4, q: "Evaluate the use of monoclonal antibodies in medicine.", scheme: ["Advantage: very specific / target one type of cell", "Advantage: many uses (diagnosis, treatment, testing)", "Disadvantage: cause more side effects than expected", "Disadvantage: expensive / difficult to produce / animal use"], answer: "Monoclonal antibodies are very specific, targeting one type of cell, and have many uses in diagnosis and treatment. However, they have caused more side effects than expected, are expensive and difficult to produce, and raise concerns about the use of animals." },
      { g: 8, marks: 3, q: "Explain why antibiotic resistance is described as a global health problem.", scheme: ["Resistant bacteria (e.g. MRSA) are hard to treat", "Infections spread between people and countries", "Fewer effective antibiotics remain / new ones are slow to develop"], answer: "Resistant bacteria such as MRSA are difficult to treat, spread between people and countries, and are outpacing the development of new antibiotics, so more infections become untreatable worldwide." },
      { g: 8, marks: 3, q: "Explain how the discovery of penicillin by Alexander Fleming happened.", scheme: ["Fleming noticed mould (Penicillium) on a bacterial plate", "Bacteria did not grow around the mould", "The mould produced a substance (penicillin) that killed bacteria"], answer: "Fleming noticed that a Penicillium mould had grown on a plate of bacteria and that no bacteria grew around it, because the mould produced penicillin, which killed the bacteria." },
      { g: 8, marks: 4, q: "Explain why developing a new drug takes many years and is expensive.", scheme: ["Must be tested for safety (toxicity) and efficacy", "Preclinical (cells, tissues, animals) then clinical trials", "Large numbers of patients over a long time", "Many potential drugs fail the testing"], answer: "A new drug must be thoroughly tested for safety and effectiveness through preclinical tests and long clinical trials on many patients, and most potential drugs fail somewhere in this process, so it is slow and costly." },
      { g: 8, marks: 3, q: "Explain how you could measure how effective an antibiotic is at killing bacteria on an agar plate.", scheme: ["Place antibiotic discs on a lawn of bacteria", "A clear zone (of inhibition) forms where bacteria are killed", "Measure the area (πr²) — a larger zone = more effective"], answer: "Place antibiotic discs on a lawn of bacteria and incubate; a clear zone of inhibition forms where bacteria are killed. The larger the area of the zone, the more effective the antibiotic." },
      { g: 8, marks: 3, q: "Analyse why a placebo group is essential in a fair drug trial.", scheme: ["Some patients improve just from being treated (placebo effect)", "The placebo group shows the natural/placebo change", "So the drug's true effect can be seen by comparison"], answer: "Some patients improve simply because they believe they are being treated (the placebo effect), so a placebo group shows this baseline, allowing the drug's true effect to be seen by comparison." },
      { g: 8, marks: 3, q: "Explain why viruses are difficult to develop drugs and vaccines against.", scheme: ["Viruses live inside body cells → hard to target", "They mutate/change their antigens", "So immunity or a drug may no longer work"], answer: "Viruses live inside the body's cells, making them hard to target without harming the cells, and they mutate so their antigens change, meaning existing immunity or drugs may no longer work." },
      { g: 8, marks: 3, q: "Explain the economic impact of plant disease and why detecting it matters.", scheme: ["Disease reduces crop yield / kills plants", "Loss of income for farmers / food shortages", "Early detection allows treatment and limits spread"], answer: "Plant diseases reduce crop yields or kill plants, causing loss of income and food shortages, so detecting them early allows treatment and limits their spread, protecting food supplies." },
      { g: 8, marks: 3, q: "Explain how HIV can lead to AIDS if untreated.", scheme: ["HIV attacks/destroys white blood cells (lymphocytes)", "The immune system becomes very weak (late-stage/AIDS)", "The body cannot fight other infections/cancers"], answer: "HIV attacks and destroys white blood cells, so if untreated the immune system becomes so weak (AIDS) that the body cannot fight off other infections or cancers." },
      { g: 8, marks: 3, q: "Explain how the body's three lines of defence work in order.", scheme: ["First: barriers (skin, mucus, acid) stop entry", "Second: phagocytes engulf pathogens that get in", "Third: lymphocytes make specific antibodies and memory cells"], answer: "First, barriers such as the skin, mucus and stomach acid stop pathogens entering; second, phagocytes engulf any that get in; and third, lymphocytes make specific antibodies and memory cells against them." },
      { g: 8, marks: 3, q: "Analyse data showing a fall in a disease after a vaccine is introduced, and explain the trend.", scheme: ["Cases fall as more people are vaccinated", "Vaccinated people are immune → fewer to spread it", "Herd immunity reduces spread to the unvaccinated"], answer: "The number of cases falls as more people are vaccinated because the vaccinated are immune and cannot spread the disease, and herd immunity means the pathogen struggles to reach the few who are unvaccinated." },
      { g: 8, marks: 3, q: "Explain why antibiotics have greatly reduced deaths from bacterial disease, and why this benefit is now threatened.", scheme: ["Antibiotics kill bacteria inside the body, curing infections", "Reduced deaths from previously fatal infections", "Overuse has led to resistant strains, threatening this"], answer: "Antibiotics kill bacteria inside the body and cure infections that were once fatal, greatly reducing deaths, but their overuse has produced resistant strains that threaten to make these infections untreatable again." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain fully how the body defends itself against pathogens, from the first barrier to long-term immunity.", scheme: ["Physical/chemical barriers: skin, mucus, cilia, stomach acid", "Phagocytes engulf and digest pathogens (non-specific)", "Lymphocytes produce specific antibodies", "Antitoxins neutralise toxins", "Memory cells remain", "Faster, stronger response on reinfection = immunity"], answer: "First, barriers such as the skin, mucus, cilia and stomach acid stop most pathogens entering. Any that get in are engulfed by phagocytes. Lymphocytes then make antibodies specific to the pathogen's antigens and antitoxins to neutralise toxins, and memory cells remain so that a future infection triggers a faster, stronger response, giving immunity." },
      { g: 9, marks: 6, q: "Evaluate the use of vaccination programmes, including herd immunity and the arguments for and against.", scheme: ["For: prevents disease, epidemics and deaths", "For: herd immunity protects the vulnerable/unvaccinated", "For: has eradicated/controlled diseases (smallpox, polio)", "Against: rare side effects; not 100% effective", "Against: some object on personal/ethical grounds", "Justified conclusion"], answer: "Vaccination prevents disease, epidemics and deaths, and through herd immunity protects the vulnerable and those who cannot be vaccinated; it has eradicated smallpox and controlled polio. There are rare side effects, it is not always fully effective, and some object on personal grounds, but overall the large benefits to public health usually outweigh the small risks." },
      { g: 9, marks: 6, q: "Explain how monoclonal antibodies are produced and evaluate their use in diagnosis and treatment.", scheme: ["Antigen injected into a mouse → lymphocytes made", "Fused with tumour cells → hybridomas → cloned", "Produce one specific antibody in large amounts", "Uses: pregnancy tests, diagnosis, targeted cancer treatment", "Advantages: specific/targeted; Disadvantages: side effects, cost, ethics", "Justified conclusion"], answer: "A mouse is injected with an antigen to make lymphocytes, which are fused with tumour cells to form hybridomas that are cloned to produce one specific antibody in large amounts. These are used in pregnancy tests, diagnosis and targeted cancer treatment. They are valuable because they are highly specific, but they can cause side effects, are expensive and raise ethical concerns, so their use must be weighed against alternatives." },
      { g: 9, marks: 6, q: "Explain how antibiotic-resistant bacteria evolve by natural selection and how the problem can be reduced.", scheme: ["Variation from random mutation → some bacteria resistant", "Antibiotics kill non-resistant bacteria", "Resistant survive and reproduce, passing on the gene", "Resistant population increases over generations", "Reduce by not overprescribing, completing courses, developing new drugs", "Global cooperation needed"], answer: "Random mutations create variation, so some bacteria are resistant. When antibiotics are used, non-resistant bacteria die but resistant ones survive and reproduce, passing on the resistance gene, so over generations the resistant population grows. The problem is reduced by not over-prescribing antibiotics, completing every course, and developing new antibiotics, which requires global cooperation." },
      { g: 9, marks: 5, q: "Design and justify a clinical trial to test whether a new drug lowers blood pressure.", scheme: ["Large group of patients split into two", "One group the drug, the other a placebo", "Double-blind: neither patients nor doctors know which", "Control variables; measure blood pressure over time", "Justify: reduces bias and shows the true effect"], answer: "Take a large group of patients with high blood pressure and split them into two: one receives the drug and the other a placebo, in a double-blind way so neither patients nor doctors know which. Control other variables and measure blood pressure over time. This design reduces bias and the placebo effect, so any real effect of the drug can be identified." },
      { g: 9, marks: 6, q: "Explain the full journey of a new drug from discovery to being prescribed, and why each stage matters.", scheme: ["Discovery (from plants, microbes or synthesis)", "Preclinical testing on cells and tissues (safety)", "Testing on animals (safety and dose)", "Clinical trials on healthy volunteers (toxicity, dose)", "Clinical trials on patients (efficacy)", "Only approved if safe and effective"], answer: "A drug is first discovered, often from plants, microbes or by design, then tested on cells and tissues and on animals to check safety and dose. It then goes through clinical trials on healthy volunteers to check toxicity and dose, and on patients to check it works. Each stage protects people from harm, and the drug is only approved if it is both safe and effective." },
      { g: 9, marks: 5, q: "Explain why a mutation in a virus can make an existing vaccine ineffective.", scheme: ["A vaccine trains memory cells against a specific antigen", "A mutation changes the virus's antigen", "Memory cells/antibodies no longer recognise it", "So the immune response is slow/ineffective", "A new vaccine may be needed"], answer: "A vaccine makes memory cells that recognise a specific antigen on the virus. If the virus mutates and its antigen changes, the memory cells and antibodies no longer recognise it, so the immune response is slow and the person can still fall ill, meaning a new vaccine may be needed." },
      { g: 9, marks: 6, q: "Explain how plant defences, disease detection and mineral supply together protect crop yields.", scheme: ["Physical, chemical and mechanical defences resist pathogens", "Early detection (signs, testing) limits spread", "Treat with fungicides / remove affected plants", "Nitrate needed for growth; magnesium for chlorophyll", "Deficiencies reduce yield → provide fertiliser", "Together they maximise healthy growth/food security"], answer: "Plants resist pathogens with physical, chemical and mechanical defences, and detecting disease early from its signs or by testing allows treatment with fungicides or removal of affected plants to limit spread. Supplying nitrate for growth and magnesium for chlorophyll prevents deficiencies that reduce yield. Together these protect healthy growth and food security." },
      { g: 9, marks: 5, q: "Compare how bacterial and viral diseases are treated, and explain why the difference exists.", scheme: ["Bacterial: antibiotics kill bacteria (act on their structures)", "Viral: antibiotics don't work; antivirals limited", "Viruses live inside cells → hard to target safely", "Painkillers relieve symptoms of both", "Prevention (vaccines/hygiene) important for viruses"], answer: "Bacterial diseases are treated with antibiotics, which kill bacteria by acting on structures they have but our cells don't. Viral diseases can't be treated with antibiotics because viruses live inside our cells and are hard to target without harming them, so treatment mainly relieves symptoms and prevention through vaccines and hygiene is key." },
      { g: 9, marks: 6, q: "Evaluate the different methods used to reduce the spread of communicable disease worldwide.", scheme: ["Hygiene/handwashing/sanitation: cheap, effective, needs behaviour change", "Vaccination: prevents disease, herd immunity, but cost/access", "Isolation/quarantine: limits spread, but disruptive", "Vector control (nets, insecticides): reduces malaria, resistance risk", "Education: supports all methods", "Justified conclusion (combination best)"], answer: "Good hygiene and sanitation are cheap and effective but rely on behaviour change; vaccination prevents disease and gives herd immunity but has cost and access issues; isolation limits spread but is disruptive; and vector control such as nets reduces malaria but risks insecticide resistance. Education supports all of these, so a combination of methods, adapted to each disease and place, works best." },
      { g: 9, marks: 5, q: "Explain, in terms of natural selection, why using antibiotics to treat a viral infection is both useless and harmful.", scheme: ["Antibiotics don't kill viruses → useless for the illness", "They still kill non-resistant bacteria in the body", "Any resistant bacteria survive and reproduce", "Increasing resistant strains", "So it speeds up resistance without curing the patient"], answer: "Antibiotics do not kill viruses, so they cannot cure a viral infection. However, they still kill non-resistant bacteria in the body, leaving resistant bacteria to survive and reproduce, which increases resistant strains. So the treatment does no good and actively speeds up the spread of antibiotic resistance." },
      { g: 9, marks: 6, q: "Explain how the structure and behaviour of white blood cells allow the body to respond to a specific pathogen and to become immune.", scheme: ["Phagocytes engulf and digest any pathogen (non-specific)", "Lymphocytes have receptors for specific antigens", "The matching lymphocyte divides and makes antibodies", "Antibodies bind the specific antigen", "Some become memory cells", "On reinfection they respond quickly → immunity"], answer: "Phagocytes engulf and digest pathogens non-specifically, while lymphocytes carry receptors for specific antigens. When a lymphocyte matches a pathogen's antigen it divides and produces antibodies that bind that antigen, and some become memory cells. If the same pathogen returns, the memory cells respond quickly, giving immunity." },
      { g: 9, marks: 5, q: "A new antibiotic works well in the lab but fails in clinical trials. Suggest and explain reasons why.", scheme: ["May be toxic/have side effects in the whole body", "May be broken down/not reach the site in the body", "Dose that works in a dish may be unsafe in people", "The body is more complex than cells in a dish", "So lab success does not guarantee it works safely in patients"], answer: "In the body the drug may be toxic or cause side effects, may be broken down before reaching the infection, or the effective dose may be unsafe. A living body is far more complex than cells in a dish, so a drug that kills bacteria in the lab may not work safely in patients, which is why clinical trials are essential." },
      { g: 9, marks: 5, q: "Explain how overuse of antibiotics in both medicine and farming contributes to resistance, and suggest solutions.", scheme: ["More antibiotic use → stronger selection pressure for resistance", "Farm use exposes many bacteria to antibiotics", "Resistant bacteria can pass to humans (food/environment)", "Solutions: reduce non-essential use in farming and medicine", "Improve hygiene; develop new drugs"], answer: "The more antibiotics are used in medicine and farming, the stronger the selection pressure favouring resistant bacteria, and resistant strains from farm animals can pass to humans through food or the environment. Solutions include reducing non-essential use in both farming and medicine, improving hygiene to limit spread, and developing new antibiotics." },
      { g: 9, marks: 6, q: "Evaluate whether monoclonal antibodies or traditional chemotherapy is better for treating cancer.", scheme: ["Monoclonal: target specific cancer cells → fewer side effects", "Monoclonal: expensive, some side effects, hard to produce", "Chemotherapy: kills dividing cells but also healthy ones → more side effects", "Chemotherapy: cheaper, well established", "Depends on cancer type/patient", "Justified conclusion"], answer: "Monoclonal antibodies target specific cancer cells, so they can cause fewer side effects than chemotherapy, which kills all rapidly dividing cells including healthy ones. However, monoclonal antibodies are expensive and harder to produce, while chemotherapy is cheaper and well established. The better choice depends on the type of cancer and the patient, and the two are often used together." },
    ],

    "4. Bioenergetics": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "Write the word equation for photosynthesis.", scheme: ["carbon dioxide + water → glucose + oxygen (light/chlorophyll)"], answer: "Carbon dioxide + water → glucose + oxygen." },
      { g: 4, marks: 1, q: "In which part of a plant cell does photosynthesis take place?", scheme: ["Chloroplasts"], answer: "In the chloroplasts." },
      { g: 4, marks: 1, q: "Which gas is released during photosynthesis?", scheme: ["Oxygen"], answer: "Oxygen." },
      { g: 4, marks: 1, q: "Is photosynthesis endothermic or exothermic?", scheme: ["Endothermic (takes in energy/light)"], answer: "Endothermic — it takes in energy from light." },
      { g: 4, marks: 1, q: "Which green pigment absorbs light for photosynthesis?", scheme: ["Chlorophyll"], answer: "Chlorophyll." },
      { g: 4, marks: 1, q: "Write the word equation for aerobic respiration.", scheme: ["glucose + oxygen → carbon dioxide + water"], answer: "Glucose + oxygen → carbon dioxide + water." },
      { g: 4, marks: 1, q: "In which organelle does most respiration happen?", scheme: ["Mitochondria"], answer: "The mitochondria." },
      { g: 4, marks: 1, q: "Is respiration exothermic or endothermic?", scheme: ["Exothermic (releases energy)"], answer: "Exothermic — it releases energy." },
      { g: 4, marks: 1, q: "What is anaerobic respiration?", scheme: ["Respiration without oxygen"], answer: "Respiration that takes place without oxygen." },
      { g: 4, marks: 1, q: "What is the product of anaerobic respiration in human muscles?", scheme: ["Lactic acid"], answer: "Lactic acid." },
      { g: 4, marks: 1, q: "What are the products of anaerobic respiration in yeast?", scheme: ["Ethanol and carbon dioxide"], answer: "Ethanol and carbon dioxide." },
      { g: 4, marks: 1, q: "What is anaerobic respiration in yeast called?", scheme: ["Fermentation"], answer: "Fermentation." },
      { g: 4, marks: 1, q: "Name three factors that affect the rate of photosynthesis.", scheme: ["Light intensity, carbon dioxide concentration, temperature"], answer: "Light intensity, carbon dioxide concentration and temperature." },
      { g: 4, marks: 1, q: "Name one use of the glucose made in photosynthesis.", scheme: ["Respiration / making starch / cellulose / proteins (any one)"], answer: "For respiration (or to make starch, cellulose or proteins)." },
      { g: 4, marks: 1, q: "Why is respiration important to living things?", scheme: ["Releases energy for life processes"], answer: "It releases energy for the body's life processes." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 1, q: "Define a limiting factor.", scheme: ["A factor that, when in short supply, limits the rate of a process"], answer: "A factor that, when in short supply, restricts the rate of a process such as photosynthesis." },
      { g: 5, marks: 1, q: "What do plants convert glucose into for storage?", scheme: ["Starch"], answer: "Starch." },
      { g: 5, marks: 2, q: "Give two uses of the energy released by respiration.", scheme: ["Any two: movement/muscle contraction, keeping warm, building larger molecules, active transport"], answer: "Movement and keeping warm (also building larger molecules and active transport)." },
      { g: 5, marks: 2, q: "State two differences between aerobic and anaerobic respiration.", scheme: ["Aerobic uses oxygen; anaerobic does not", "Aerobic releases more energy than anaerobic"], answer: "Aerobic respiration uses oxygen and releases more energy; anaerobic respiration does not use oxygen and releases less energy." },
      { g: 5, marks: 1, q: "Why does anaerobic respiration release less energy than aerobic?", scheme: ["Glucose is not completely broken down"], answer: "Because the glucose is only partly (not completely) broken down." },
      { g: 5, marks: 1, q: "Define metabolism.", scheme: ["The sum of all the chemical reactions in a cell or the body"], answer: "The sum of all the chemical reactions in a cell or the body." },
      { g: 5, marks: 1, q: "State the products of aerobic respiration.", scheme: ["Carbon dioxide and water"], answer: "Carbon dioxide and water." },
      { g: 5, marks: 1, q: "What is 'oxygen debt'?", scheme: ["The extra oxygen needed after exercise to remove/break down lactic acid"], answer: "The extra oxygen the body needs after exercise to break down the lactic acid that built up." },
      { g: 5, marks: 1, q: "Why does a plant need nitrate ions?", scheme: ["To make proteins / amino acids"], answer: "To make amino acids and proteins." },
      { g: 5, marks: 1, q: "State the relationship between light intensity and distance from a lamp.", scheme: ["Light intensity is proportional to 1/distance² (inverse square law)"], answer: "Light intensity is proportional to 1 ÷ distance² (the inverse square law)." },
      { g: 5, marks: 2, q: "Give three uses of glucose in a plant.", scheme: ["Any three: respiration, making starch, cellulose, proteins (with nitrate), stored as lipids"], answer: "For respiration, to make starch for storage, and to make cellulose (also proteins and lipids)." },
      { g: 5, marks: 1, q: "How is yeast used in brewing?", scheme: ["Anaerobic respiration (fermentation) produces ethanol and CO2"], answer: "Yeast respires anaerobically (ferments), producing ethanol." },
      { g: 5, marks: 1, q: "What happens to the rate of photosynthesis as light intensity increases (at low light)?", scheme: ["The rate increases"], answer: "The rate of photosynthesis increases." },
      { g: 5, marks: 1, q: "Why is starch used for storage rather than glucose?", scheme: ["Starch is insoluble so does not affect water balance/osmosis"], answer: "Because starch is insoluble, so it does not affect the cell's water balance by osmosis." },
      { g: 5, marks: 1, q: "Name the raw materials for photosynthesis.", scheme: ["Carbon dioxide and water"], answer: "Carbon dioxide and water." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why photosynthesis is described as endothermic.", scheme: ["It takes in / absorbs energy", "The energy comes from light"], answer: "It is endothermic because it absorbs energy — the energy needed for the reaction comes from light." },
      { g: 6, marks: 2, q: "Explain why muscles respire anaerobically during vigorous exercise.", scheme: ["Oxygen cannot be delivered fast enough", "So respiration continues without oxygen to release energy"], answer: "During hard exercise oxygen cannot be supplied to the muscles fast enough, so they respire anaerobically to keep releasing energy." },
      { g: 6, marks: 2, q: "Explain how increasing carbon dioxide concentration affects photosynthesis.", scheme: ["CO2 is a raw material, so more increases the rate", "Until another factor becomes limiting"], answer: "Carbon dioxide is a raw material, so increasing it speeds up photosynthesis until another factor (like light or temperature) becomes limiting." },
      { g: 6, marks: 2, q: "Explain the effect of temperature on the rate of photosynthesis.", scheme: ["Rate increases with temperature up to an optimum", "Above the optimum enzymes denature and the rate falls"], answer: "The rate rises as temperature increases up to an optimum, but above it the enzymes denature and the rate falls." },
      { g: 6, marks: 2, q: "Explain why farmers grow crops in greenhouses.", scheme: ["To control light, temperature and CO2", "To increase the rate of photosynthesis and so the yield"], answer: "Greenhouses let farmers control light, temperature and CO2 to increase photosynthesis and therefore crop yield." },
      { g: 6, marks: 2, q: "Explain why lactic acid causes a problem during exercise.", scheme: ["It builds up in muscles", "Causes fatigue/cramp and creates an oxygen debt"], answer: "Lactic acid builds up in the muscles, causing fatigue and cramp, and creates an oxygen debt that must be repaid." },
      { g: 6, marks: 2, q: "A lamp is moved from 10 cm to 20 cm from pondweed. Explain what happens to the light intensity.", scheme: ["Distance doubled → intensity falls to a quarter", "Because intensity ∝ 1/distance²"], answer: "Doubling the distance reduces the light intensity to a quarter, because intensity is proportional to 1 ÷ distance²." },
      { g: 6, marks: 2, q: "Explain why breathing rate stays high for a while after exercise stops.", scheme: ["To take in extra oxygen (oxygen debt)", "To break down the lactic acid that built up"], answer: "Breathing stays fast to take in the extra oxygen needed to break down the lactic acid that built up during exercise." },
      { g: 6, marks: 2, q: "Explain why a plant kept in the dark eventually dies.", scheme: ["No photosynthesis, so no new glucose", "Stored glucose runs out; cannot respire, so it dies"], answer: "Without light it cannot photosynthesise to make glucose, so once its stored glucose runs out it cannot respire and it dies." },
      { g: 6, marks: 2, q: "Explain why the rate of photosynthesis levels off at very high light intensity.", scheme: ["Light is no longer the limiting factor", "Another factor (CO2 or temperature) now limits the rate"], answer: "At high light intensity, light is no longer limiting, so another factor such as carbon dioxide or temperature limits the rate." },
      { g: 6, marks: 2, q: "Explain how glucose is used to make proteins in a plant.", scheme: ["Glucose combined with nitrate ions (from the soil)", "To make amino acids, which join to form proteins"], answer: "The plant combines glucose with nitrate ions from the soil to make amino acids, which are joined together to make proteins." },
      { g: 6, marks: 2, q: "Explain why respiration continues in plants during the night.", scheme: ["Energy is needed all the time for life processes", "Photosynthesis stops in the dark but respiration does not"], answer: "Plants need energy constantly for their life processes, so they respire day and night even though they only photosynthesise in the light." },
      { g: 6, marks: 2, q: "Explain how you could measure the rate of photosynthesis of pondweed.", scheme: ["Count the bubbles of oxygen released per minute", "Or measure the volume of gas collected in a set time"], answer: "By counting the number of oxygen bubbles released per minute, or measuring the volume of gas produced in a set time." },
      { g: 6, marks: 2, q: "Explain how yeast is used to make bread rise.", scheme: ["Yeast ferments sugars producing carbon dioxide", "The CO2 gas makes the dough rise"], answer: "Yeast ferments the sugars in the dough, producing carbon dioxide gas that makes the dough rise." },
      { g: 6, marks: 2, q: "Explain why aerobic respiration is more useful than anaerobic for everyday activity.", scheme: ["Releases much more energy per glucose", "Does not produce lactic acid"], answer: "Aerobic respiration releases far more energy from each glucose molecule and does not produce lactic acid, so it suits everyday activity." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Describe how you would investigate the effect of light intensity on the rate of photosynthesis using pondweed.", scheme: ["Place pondweed in water with sodium hydrogencarbonate (CO2)", "Lamp at set distances from the pondweed", "Count oxygen bubbles (or gas volume) per minute at each distance", "Control temperature and CO2; repeat and take a mean"], answer: "Place pondweed in water containing sodium hydrogencarbonate, put a lamp at set distances and count the oxygen bubbles produced per minute at each distance, keeping temperature and CO2 constant and repeating for a mean." },
      { g: 7, marks: 3, q: "The light intensity 10 cm from a lamp is 100 units. Use the inverse square law to find the intensity at 20 cm and 30 cm.", scheme: ["Intensity ∝ 1/d²", "At 20 cm (2×): 100 ÷ 4 = 25 units", "At 30 cm (3×): 100 ÷ 9 ≈ 11 units"], answer: "As intensity ∝ 1/d²: at 20 cm it is 100 ÷ 2² = 25 units, and at 30 cm it is 100 ÷ 3² ≈ 11 units." },
      { g: 7, marks: 3, q: "Explain how the products of anaerobic respiration differ between humans, plants and yeast.", scheme: ["Humans: glucose → lactic acid", "Plants and yeast: glucose → ethanol + carbon dioxide"], answer: "In humans anaerobic respiration produces lactic acid, whereas in plants and yeast it produces ethanol and carbon dioxide." },
      { g: 7, marks: 4, q: "Explain fully what oxygen debt is and how the body repays it.", scheme: ["Anaerobic respiration in muscles produces lactic acid", "Oxygen debt is the extra oxygen needed to remove it", "Blood carries lactic acid to the liver", "It is oxidised (converted) to CO2 and water"], answer: "During hard exercise muscles respire anaerobically, producing lactic acid. The oxygen debt is the extra oxygen needed afterwards to remove it: blood carries the lactic acid to the liver, where it is oxidised to carbon dioxide and water." },
      { g: 7, marks: 3, q: "Explain, using limiting factors, the shape of a graph of photosynthesis rate against light intensity.", scheme: ["At low light the rate rises as light increases (light is limiting)", "The line then levels off", "Another factor (CO2 or temperature) has become limiting"], answer: "At low light intensity the rate rises steeply as light is the limiting factor, then the graph levels off because another factor such as CO2 or temperature has become limiting." },
      { g: 7, marks: 3, q: "Explain why a market gardener might add a paraffin heater in a greenhouse, despite the cost.", scheme: ["It raises temperature and releases CO2", "Both increase the rate of photosynthesis", "Increased yield/profit outweighs the cost"], answer: "The heater raises the temperature and releases carbon dioxide, both of which increase photosynthesis, so the extra yield and profit outweigh the running cost." },
      { g: 7, marks: 3, q: "Compare the amount of energy released by aerobic and anaerobic respiration and explain the difference.", scheme: ["Aerobic releases much more energy", "Because glucose is completely broken down", "Anaerobic breaks glucose down only partly"], answer: "Aerobic respiration releases much more energy because the glucose is completely broken down, whereas anaerobic respiration only partly breaks it down, releasing less." },
      { g: 7, marks: 3, q: "Describe how glucose made in photosynthesis is used to make three different substances.", scheme: ["With nitrates → amino acids/proteins", "→ cellulose for cell walls", "→ lipids/oils for storage (or starch for storage)"], answer: "Glucose is combined with nitrates to make proteins, converted into cellulose for cell walls, and turned into lipids or starch for storage." },
      { g: 7, marks: 3, q: "Explain how temperature affects both photosynthesis and respiration in a similar way.", scheme: ["Both are controlled by enzymes", "Rate increases with temperature up to an optimum", "Above the optimum enzymes denature and rate falls"], answer: "Both are enzyme-controlled, so their rates increase with temperature up to an optimum, then fall as the enzymes denature above it." },
      { g: 7, marks: 3, q: "A student counts 30 oxygen bubbles in 2 minutes. Calculate the rate and suggest how to improve reliability.", scheme: ["Rate = 30 ÷ 2 = 15 bubbles per minute", "Repeat and take a mean", "Control variables (temperature, CO2)"], answer: "The rate is 30 ÷ 2 = 15 bubbles per minute. To improve reliability, repeat the count and take a mean, and control the temperature and CO2." },
      { g: 7, marks: 3, q: "Explain why increasing all three limiting factors together does not increase yield without limit.", scheme: ["There is always some factor in shortest supply", "That factor limits the rate", "Other limits (e.g. amount of chlorophyll) also apply"], answer: "There is always one factor in shortest supply that limits the rate, and other limits such as the amount of chlorophyll mean the rate cannot increase indefinitely." },
      { g: 7, marks: 3, q: "Explain how the response of the heart and lungs to exercise supports increased respiration.", scheme: ["Heart rate increases → more blood/oxygen/glucose to muscles", "Breathing rate/depth increases → more oxygen in, more CO2 out", "Supports faster aerobic respiration"], answer: "The heart beats faster to deliver more oxygen and glucose to the muscles, and breathing becomes faster and deeper to take in more oxygen and remove carbon dioxide, supporting faster aerobic respiration." },
      { g: 7, marks: 3, q: "Explain why measuring oxygen released may underestimate the true rate of photosynthesis.", scheme: ["The plant also respires, using up some oxygen", "So the oxygen measured is the net amount (photosynthesis − respiration)"], answer: "The plant is also respiring and using up some oxygen, so the oxygen measured is the net amount, which is less than the true amount produced by photosynthesis." },
      { g: 7, marks: 2, q: "Explain why yeast used in brewing is kept warm and without oxygen.", scheme: ["Warmth speeds enzyme-controlled fermentation", "No oxygen ensures anaerobic respiration → ethanol"], answer: "Warmth speeds up the enzyme-controlled reactions, and the lack of oxygen forces anaerobic respiration, producing ethanol." },
      { g: 7, marks: 3, q: "Sketch and explain how the rate of photosynthesis changes as temperature rises from 0 °C to 45 °C.", scheme: ["Rate rises with temperature to an optimum (~around 30-40 °C)", "Then falls sharply", "Because enzymes denature at high temperature"], answer: "The rate increases with temperature to an optimum around 30–40 °C, then falls sharply because the enzymes controlling photosynthesis denature at high temperatures." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain fully how light intensity, carbon dioxide and temperature act as interacting limiting factors of photosynthesis.", scheme: ["At any time the factor in shortest supply limits the rate", "Increasing a limiting factor increases the rate until another becomes limiting", "Light and CO2 are raw materials/energy source", "Temperature affects the enzymes (optimum, then denature)"], answer: "At any moment the factor in shortest supply limits the rate. Increasing that factor raises the rate until a different factor becomes limiting. Light provides energy and CO2 is a raw material, while temperature affects the enzymes, speeding the rate up to an optimum before denaturing them." },
      { g: 8, marks: 4, q: "Explain fully the process of oxygen debt and its removal after strenuous exercise.", scheme: ["Insufficient oxygen → muscles respire anaerobically", "Produces lactic acid, causing fatigue", "After exercise, extra oxygen (the debt) is taken in", "Lactic acid transported to the liver and oxidised to CO2 and water"], answer: "When oxygen is insufficient the muscles respire anaerobically, producing lactic acid and causing fatigue. After exercise the body takes in extra oxygen (the oxygen debt) and transports the lactic acid in the blood to the liver, where it is oxidised to carbon dioxide and water." },
      { g: 8, marks: 4, q: "Analyse a graph where photosynthesis rate rises with CO2 then plateaus, explaining the limiting factor at each stage.", scheme: ["Rising part: CO2 is the limiting factor", "Adding CO2 increases the rate", "Plateau: CO2 no longer limiting", "Another factor (light or temperature) now limits the rate"], answer: "On the rising part CO2 is limiting, so adding more increases the rate. On the plateau CO2 is no longer limiting, so another factor such as light intensity or temperature is now controlling the rate." },
      { g: 8, marks: 3, q: "Explain why anaerobic respiration is less efficient than aerobic respiration and give a consequence.", scheme: ["Glucose only partly broken down → less energy released", "Produces lactic acid (humans)", "Causes fatigue / an oxygen debt"], answer: "Anaerobic respiration only partly breaks glucose down, so it releases much less energy, and it produces lactic acid that causes fatigue and an oxygen debt." },
      { g: 8, marks: 4, q: "Evaluate whether it is worth a farmer controlling all the conditions in a greenhouse.", scheme: ["Controlling light, CO2, temperature increases photosynthesis and yield", "Higher yield/profit and out-of-season crops", "But equipment and energy are expensive", "Judgement: worthwhile if extra profit exceeds the cost"], answer: "Controlling light, CO2 and temperature increases photosynthesis and yield and allows out-of-season crops, raising profit. However, the equipment and energy are costly, so it is only worthwhile if the extra income outweighs these costs." },
      { g: 8, marks: 4, q: "Explain how the body responds to exercise to increase the rate of aerobic respiration.", scheme: ["Heart rate increases → faster delivery of oxygen and glucose", "Breathing rate and depth increase → more oxygen absorbed, CO2 removed", "Muscles receive more raw materials for respiration", "If oxygen still insufficient, anaerobic respiration occurs"], answer: "During exercise the heart beats faster to deliver oxygen and glucose more quickly, and breathing becomes faster and deeper to absorb more oxygen and remove carbon dioxide, supplying the muscles for faster aerobic respiration; if oxygen is still insufficient, anaerobic respiration also occurs." },
      { g: 8, marks: 4, q: "Explain how metabolism links respiration with the building of larger molecules in an organism.", scheme: ["Respiration releases energy from glucose", "Energy used to build larger molecules", "e.g. glucose → starch/cellulose; glucose + nitrate → amino acids → proteins; → lipids", "These reactions together make up metabolism"], answer: "Respiration releases energy from glucose, and this energy is used to build larger molecules — for example turning glucose into starch or cellulose, combining it with nitrate to make amino acids and proteins, or making lipids. All these reactions together make up metabolism." },
      { g: 8, marks: 3, q: "Evaluate a method that measures photosynthesis by counting oxygen bubbles, suggesting two improvements.", scheme: ["Bubbles may be different sizes → unreliable", "Better: measure gas volume with a gas syringe", "Control temperature (lamp heat) with a water bath/heat shield; repeat"], answer: "Counting bubbles is unreliable because bubbles vary in size; it is better to collect the gas in a syringe and measure its volume. The lamp's heat should also be controlled with a water bath or heat shield, and the experiment repeated for a mean." },
      { g: 8, marks: 3, q: "Explain why the inverse square law must be considered when placing a lamp in a photosynthesis experiment.", scheme: ["Light intensity falls with the square of distance", "Small changes in distance cause large changes in intensity", "So distance must be measured and used accurately as the variable"], answer: "Light intensity falls with the square of the distance, so even a small change in distance causes a large change in intensity; the distance must therefore be measured accurately and converted to intensity using 1/d²." },
      { g: 8, marks: 3, q: "Explain how a plant's uses of glucose help it grow and survive.", scheme: ["Respiration for energy", "Starch for energy store", "Cellulose for strong cell walls (growth/support)", "Proteins for growth and enzymes"], answer: "Glucose is respired for energy, stored as starch, made into cellulose for strong cell walls, and combined with nitrate to make proteins for growth and enzymes — all supporting growth and survival." },
      { g: 8, marks: 3, q: "Analyse data showing aerobic respiration releases about 16 times more energy than anaerobic, and explain why.", scheme: ["Aerobic completely oxidises glucose to CO2 and water", "Releasing much more energy", "Anaerobic only partly breaks glucose down (to lactic acid/ethanol)"], answer: "Aerobic respiration completely oxidises glucose to carbon dioxide and water, releasing far more energy, whereas anaerobic respiration only partly breaks it down to lactic acid or ethanol, releasing much less." },
      { g: 8, marks: 3, q: "Explain why the rate of photosynthesis is important to the whole food chain.", scheme: ["Plants are producers, making glucose/biomass", "This energy passes to consumers when eaten", "So photosynthesis rate limits the energy available to the ecosystem"], answer: "Plants are producers that use photosynthesis to make glucose and biomass; this energy passes to consumers along the food chain, so the rate of photosynthesis limits the energy available to the whole ecosystem." },
      { g: 8, marks: 3, q: "Explain how yeast fermentation is used differently in brewing and baking.", scheme: ["Brewing: ethanol is the useful product (CO2 released)", "Baking: CO2 is the useful product (makes dough rise); ethanol evaporates on cooking", "Both are anaerobic respiration of yeast"], answer: "Both use anaerobic respiration of yeast, but in brewing the useful product is the ethanol, while in baking it is the carbon dioxide that makes the dough rise, with the ethanol evaporating during cooking." },
      { g: 8, marks: 3, q: "Explain why plants photosynthesise and respire at the same time during the day, and what this means for gas exchange.", scheme: ["Both processes occur in the light", "In bright light photosynthesis exceeds respiration → net O2 out, CO2 in", "Rates depend on light intensity"], answer: "In daylight a plant both photosynthesises and respires; in bright light photosynthesis exceeds respiration, so overall it takes in carbon dioxide and gives out oxygen, with the balance depending on the light intensity." },
      { g: 8, marks: 3, q: "Explain how a lack of magnesium or nitrate would reduce a plant's rate of photosynthesis or growth.", scheme: ["Magnesium needed to make chlorophyll → less chlorophyll → less light absorbed → slower photosynthesis", "Nitrate needed for proteins → poor growth"], answer: "Magnesium is needed to make chlorophyll, so a deficiency reduces light absorption and slows photosynthesis, while nitrate is needed to make proteins, so a deficiency stunts the plant's growth." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain fully how limiting factors interact to control photosynthesis and how commercial growers use this knowledge.", scheme: ["Light, CO2 and temperature can each limit the rate", "The factor in shortest supply limits the rate", "Increasing it raises the rate until another factor limits", "Temperature also affects enzymes (optimum then denature)", "Growers control all three in greenhouses/polytunnels", "To maximise yield where profit exceeds cost"], answer: "Light, carbon dioxide and temperature can each limit photosynthesis, with the factor in shortest supply controlling the rate; increasing it raises the rate until another becomes limiting, while temperature also affects the enzymes. Commercial growers use this by controlling all three in greenhouses — adding lighting, CO2 and heating — to maximise yield wherever the extra profit outweighs the cost." },
      { g: 9, marks: 6, q: "Compare aerobic and anaerobic respiration in humans, plants and microorganisms, including energy yield and products.", scheme: ["Aerobic (all): glucose + oxygen → CO2 + water, most energy", "Anaerobic in humans: glucose → lactic acid", "Anaerobic in plants/yeast: glucose → ethanol + CO2", "Anaerobic releases less energy (glucose only partly broken down)", "Aerobic in mitochondria; anaerobic in cytoplasm", "Anaerobic in humans causes an oxygen debt"], answer: "Aerobic respiration in all organisms fully oxidises glucose to carbon dioxide and water, releasing the most energy in the mitochondria. Anaerobic respiration releases far less energy because glucose is only partly broken down: in humans it produces lactic acid (causing an oxygen debt), while in plants and yeast it produces ethanol and carbon dioxide." },
      { g: 9, marks: 6, q: "Explain the full biological response of the body to a period of vigorous exercise, from respiration to recovery.", scheme: ["Muscles respire faster; heart rate and breathing increase", "More oxygen and glucose delivered, more CO2 removed", "If oxygen insufficient, anaerobic respiration → lactic acid", "Lactic acid causes fatigue and an oxygen debt", "After exercise, deep breathing continues to repay the debt", "Lactic acid taken to the liver and oxidised"], answer: "During exercise the muscles respire faster, so heart rate and breathing increase to deliver more oxygen and glucose and remove more carbon dioxide. If oxygen is insufficient the muscles respire anaerobically, producing lactic acid that causes fatigue and an oxygen debt. After exercise deep breathing continues to repay this debt, and the lactic acid is carried to the liver and oxidised to carbon dioxide and water." },
      { g: 9, marks: 5, q: "Design and justify an investigation into the effect of carbon dioxide concentration on the rate of photosynthesis.", scheme: ["Vary CO2 using different concentrations of sodium hydrogencarbonate", "Keep light intensity, temperature and pondweed the same", "Measure oxygen produced (bubbles or gas volume) per minute", "Repeat and take a mean", "Justify: controlling variables isolates the effect of CO2"], answer: "Use pondweed in solutions of different sodium hydrogencarbonate concentrations to vary CO2, keeping light intensity, temperature and the pondweed the same, and measure the oxygen produced per minute. Repeat for a mean. Controlling the other variables ensures any change in rate is due to CO2 alone, making the result valid." },
      { g: 9, marks: 6, q: "Explain how photosynthesis and respiration are linked in a plant over a 24-hour period, including the compensation point.", scheme: ["Day: photosynthesis and respiration both occur", "In bright light photosynthesis > respiration (net O2 out)", "Night: only respiration (net CO2 out)", "At dawn/dusk the rates can be equal", "Compensation point: photosynthesis = respiration (no net gas exchange)", "Products of one process are raw materials for the other"], answer: "During the day a plant both photosynthesises and respires; in bright light photosynthesis exceeds respiration so it gives out oxygen overall, while at night only respiration occurs so it gives out carbon dioxide. At dawn and dusk the two rates can be equal — the compensation point — where there is no net gas exchange. The products of each process (oxygen/glucose and CO2/water) serve as raw materials for the other." },
      { g: 9, marks: 6, q: "Evaluate the biological and economic arguments for artificially controlling greenhouse conditions to grow crops.", scheme: ["Biological: higher photosynthesis → more biomass/yield; out-of-season growth", "Optimising light, CO2, temperature and water", "Economic: higher yield and profit, premium prices", "But costs of heating, lighting, CO2 and equipment", "Environmental cost of energy use", "Justified conclusion balancing yield gain against cost"], answer: "Biologically, controlling light, CO2, temperature and water maximises photosynthesis, increasing yield and allowing out-of-season crops. Economically this can raise profit through greater and premium-priced harvests, but the heating, lighting, CO2 and equipment are expensive and use a lot of energy with an environmental cost. It is therefore justified only where the extra income clearly exceeds these costs." },
      { g: 9, marks: 5, q: "Explain why measuring the net gas exchange of a plant does not give the true rate of photosynthesis, and how you could account for this.", scheme: ["The plant respires as well as photosynthesises", "Net gas exchange = photosynthesis − respiration", "So measured photosynthesis is underestimated", "Measure respiration in the dark separately", "Add it to the net rate to find true photosynthesis"], answer: "A plant respires at the same time as it photosynthesises, so the gas exchange measured is the net amount (photosynthesis minus respiration), underestimating the true rate. You could measure the plant's respiration in the dark and add this to the net rate to find the true rate of photosynthesis." },
      { g: 9, marks: 6, q: "Explain how the products of photosynthesis are converted into all the main substances a plant needs.", scheme: ["Glucose used in respiration for energy", "Stored as insoluble starch", "Converted to cellulose for cell walls", "Combined with nitrate ions to make amino acids → proteins", "Used to make lipids/oils for storage (e.g. in seeds)", "Energy from respiration drives these syntheses"], answer: "Glucose from photosynthesis is respired for energy, stored as insoluble starch, and converted into cellulose for cell walls. Combined with nitrate ions it forms amino acids that build proteins, and it is also used to make lipids for storage such as in seeds. The energy released by respiration powers all these synthesis reactions." },
      { g: 9, marks: 5, q: "A student's photosynthesis results are inconsistent. Explain the likely sources of error and how to make the investigation valid and reliable.", scheme: ["Lamp heat raises temperature (uncontrolled variable) → use a heat shield/water bath", "Bubble counting unreliable → measure gas volume", "Background light varies → do in a dark room", "Repeat and take means for reliability", "Control CO2 and pondweed size for validity"], answer: "Errors likely include the lamp heating the water (changing temperature) — use a heat shield or water bath; unreliable bubble counting — measure gas volume instead; and changing background light — work in a dark room. Repeating for means improves reliability, and controlling CO2 and the size of pondweed keeps it valid." },
      { g: 9, marks: 6, q: "Explain, with biochemical reasoning, why aerobic respiration releases far more energy than anaerobic respiration, and the consequences for the body.", scheme: ["Aerobic completely oxidises glucose to CO2 and water", "Releasing a large amount of energy (much more per glucose)", "Anaerobic only partly breaks glucose to lactic acid", "Little energy released and a toxic product accumulates", "Consequence: muscles fatigue and an oxygen debt forms", "Body must repay the debt afterwards"], answer: "Aerobic respiration completely oxidises glucose to carbon dioxide and water, releasing a large amount of energy per glucose molecule. Anaerobic respiration only partly breaks glucose down to lactic acid, releasing little energy and building up a toxic product. As a result the muscles fatigue and an oxygen debt forms, which the body must repay after exercise by oxidising the lactic acid in the liver." },
      { g: 9, marks: 5, q: "Explain how limiting factors and the inverse square law together explain a graph of photosynthesis rate against distance from a lamp.", scheme: ["As distance increases, intensity falls as 1/d²", "Close up, light is high → CO2/temperature may limit (plateau)", "Further away, light becomes the limiting factor", "So rate falls steeply with distance", "Rate ∝ light intensity ∝ 1/d² in the light-limited region"], answer: "As the lamp moves away, light intensity falls with the square of the distance. Close to the lamp light is plentiful, so CO2 or temperature limits the rate and it plateaus; further away light becomes the limiting factor, so the rate falls, roughly in proportion to 1/d² in the light-limited region." },
      { g: 9, marks: 6, q: "Explain how respiration, photosynthesis and biosynthesis are integrated within a plant's metabolism.", scheme: ["Photosynthesis makes glucose using light energy", "Respiration releases energy from glucose", "That energy powers biosynthesis reactions", "Glucose is the raw material for starch, cellulose, proteins, lipids", "Products of one process feed the others (e.g. O2/CO2 cycling)", "All these reactions together are the plant's metabolism"], answer: "Photosynthesis uses light energy to make glucose, respiration releases energy from that glucose, and this energy powers biosynthesis — building starch, cellulose, proteins and lipids from glucose and other raw materials. The products of each process feed the others, and together all these linked reactions make up the plant's metabolism." },
      { g: 9, marks: 5, q: "Design an experiment to compare the rate of respiration of germinating and dormant (dry) seeds, and justify your method.", scheme: ["Place germinating seeds and dry seeds in separate sealed tubes", "Use a coloured liquid/manometer or CO2 indicator to measure gas change", "Kill/soak controls to check it's respiration", "Same temperature, number/mass of seeds, time", "Justify: controls and controlled variables give a fair comparison"], answer: "Put equal masses of germinating seeds and of dry (or boiled) seeds in separate sealed tubes with a CO2 indicator or a manometer, at the same temperature and for the same time, and compare the gas changes. Boiled seeds act as a control to show any change is due to living respiration. Controlling these variables makes the comparison fair and valid." },
      { g: 9, marks: 5, q: "Explain why a plant needs to respire even though it makes its own glucose by photosynthesis.", scheme: ["Photosynthesis stores energy in glucose but does not release usable energy", "Respiration releases the energy from glucose for cells to use", "Needed for active transport, building molecules, growth", "Occurs all the time, including in the dark", "So both processes are essential"], answer: "Photosynthesis stores energy in glucose but does not release it in a usable form; respiration releases that energy for the cells to use in active transport, building molecules and growth. Because this energy is needed all the time, including at night, a plant must respire as well as photosynthesise." },
      { g: 9, marks: 6, q: "Evaluate the claim that 'controlling temperature is the most important factor for maximising photosynthesis'.", scheme: ["Temperature affects the enzymes → too low slows, too high denatures", "But light and CO2 are also essential and often limiting", "Any of the three can be the limiting factor", "The 'most important' factor depends on conditions", "In cool climates temperature may matter most; in others light/CO2", "Justified conclusion: no single factor is always most important"], answer: "Temperature is important because it affects the enzymes — too low slows photosynthesis and too high denatures them — but light and CO2 are equally essential and are often the limiting factor. Since any of the three can limit the rate depending on the conditions, no single factor is always most important, so the claim is only true in particular situations such as a cold climate." },
    ],

    "5. Homeostasis and response": [
      // ---------------- GRADE 4 ----------------
      { g: 4, marks: 1, q: "What is homeostasis?", scheme: ["Keeping the internal conditions of the body constant / within a stable range"], answer: "Keeping the body's internal conditions constant within a stable range." },
      { g: 4, marks: 1, q: "Name two conditions controlled by homeostasis.", scheme: ["Any two: body temperature, blood glucose, water level, ion level, CO2 level"], answer: "Body temperature and blood glucose (also water and ion levels)." },
      { g: 4, marks: 1, q: "What two organs make up the central nervous system (CNS)?", scheme: ["The brain and spinal cord"], answer: "The brain and the spinal cord." },
      { g: 4, marks: 1, q: "What are the cells that carry electrical impulses called?", scheme: ["Neurones (nerve cells)"], answer: "Neurones." },
      { g: 4, marks: 1, q: "What is a reflex action?", scheme: ["A fast, automatic response that does not involve conscious thought"], answer: "A rapid, automatic response that does not involve conscious thought." },
      { g: 4, marks: 1, q: "What is a stimulus?", scheme: ["A change in the environment that is detected"], answer: "A change in the environment that is detected by the body." },
      { g: 4, marks: 1, q: "What detects a stimulus?", scheme: ["A receptor"], answer: "A receptor." },
      { g: 4, marks: 1, q: "What is the gap between two neurones called?", scheme: ["A synapse"], answer: "A synapse." },
      { g: 4, marks: 1, q: "Which organ controls blood glucose by releasing insulin?", scheme: ["The pancreas"], answer: "The pancreas." },
      { g: 4, marks: 1, q: "Which hormone lowers blood glucose?", scheme: ["Insulin"], answer: "Insulin." },
      { g: 4, marks: 1, q: "What is the endocrine system?", scheme: ["Glands that release hormones into the blood"], answer: "A system of glands that release hormones into the blood." },
      { g: 4, marks: 1, q: "What is a hormone?", scheme: ["A chemical messenger carried in the blood"], answer: "A chemical messenger carried in the blood." },
      { g: 4, marks: 1, q: "Name the main female reproductive hormone made in the ovaries.", scheme: ["Oestrogen"], answer: "Oestrogen." },
      { g: 4, marks: 1, q: "Name the main male reproductive hormone.", scheme: ["Testosterone"], answer: "Testosterone." },
      { g: 4, marks: 1, q: "What is an effector?", scheme: ["A muscle or a gland that carries out a response"], answer: "A muscle or gland that carries out a response." },

      // ---------------- GRADE 5 ----------------
      { g: 5, marks: 2, q: "Define homeostasis and say why it matters.", scheme: ["Regulation of internal conditions to keep them stable", "Maintains the right conditions for cells/enzymes to work"], answer: "Homeostasis is the regulation of the body's internal conditions to keep them stable, maintaining the right conditions for cells and enzymes to work." },
      { g: 5, marks: 2, q: "State the order of the parts of a reflex arc.", scheme: ["Stimulus → receptor → sensory neurone → relay neurone (CNS) → motor neurone → effector → response"], answer: "Stimulus → receptor → sensory neurone → relay neurone → motor neurone → effector → response." },
      { g: 5, marks: 1, q: "What happens at a synapse?", scheme: ["A chemical (neurotransmitter) diffuses across the gap and triggers an impulse in the next neurone"], answer: "A chemical (neurotransmitter) diffuses across the gap and sets off an impulse in the next neurone." },
      { g: 5, marks: 2, q: "State two differences between the nervous and endocrine systems.", scheme: ["Nervous: fast, short-lived, electrical impulses", "Endocrine: slower, longer-lasting, chemical hormones"], answer: "The nervous system is fast, short-lived and uses electrical impulses; the endocrine system is slower, longer-lasting and uses chemical hormones." },
      { g: 5, marks: 1, q: "State the function of insulin.", scheme: ["Lowers blood glucose (cells take up glucose / stored as glycogen)"], answer: "It lowers blood glucose by making cells take up glucose and the liver store it as glycogen." },
      { g: 5, marks: 1, q: "State the function of glucagon.", scheme: ["Raises blood glucose (glycogen → glucose)"], answer: "It raises blood glucose by making the liver convert glycogen back into glucose." },
      { g: 5, marks: 1, q: "State the cause of Type 1 diabetes.", scheme: ["The pancreas does not produce enough (or any) insulin"], answer: "The pancreas does not produce enough insulin." },
      { g: 5, marks: 1, q: "State how Type 1 diabetes is treated.", scheme: ["Insulin injections"], answer: "With insulin injections." },
      { g: 5, marks: 1, q: "State the cause of Type 2 diabetes.", scheme: ["Body cells stop responding to insulin (often linked to obesity)"], answer: "The body's cells stop responding properly to insulin, often linked to obesity." },
      { g: 5, marks: 2, q: "Name the four hormones that control the menstrual cycle.", scheme: ["FSH and LH", "Oestrogen and progesterone"], answer: "FSH, LH, oestrogen and progesterone." },
      { g: 5, marks: 1, q: "State the role of FSH in the menstrual cycle.", scheme: ["Causes an egg to mature in the ovary"], answer: "It causes an egg to mature in the ovary." },
      { g: 5, marks: 1, q: "State the role of LH in the menstrual cycle.", scheme: ["Triggers ovulation (release of the egg)"], answer: "It triggers ovulation — the release of the egg." },
      { g: 5, marks: 1, q: "What does a negative feedback system do?", scheme: ["Reverses a change to bring a condition back to normal"], answer: "It reverses a change to bring the condition back to its normal level." },
      { g: 5, marks: 1, q: "Name the 'master gland' and where it is.", scheme: ["The pituitary gland, in the brain"], answer: "The pituitary gland, found in the brain." },
      { g: 5, marks: 1, q: "State what an effector does in response to an impulse.", scheme: ["Muscles contract; glands secrete hormones/substances"], answer: "Muscles contract and glands release hormones or other substances." },

      // ---------------- GRADE 6 ----------------
      { g: 6, marks: 2, q: "Explain why reflex actions are important.", scheme: ["They are fast and automatic", "They protect the body from harm/danger"], answer: "Reflexes are fast and automatic, which protects the body from harm because there is no delay for conscious thought." },
      { g: 6, marks: 3, q: "Explain how an impulse passes across a synapse.", scheme: ["Impulse triggers release of a neurotransmitter chemical", "It diffuses across the gap", "It binds to receptors and starts a new impulse in the next neurone"], answer: "The arriving impulse makes the neurone release a neurotransmitter, which diffuses across the gap and binds to receptors on the next neurone, starting a new impulse." },
      { g: 6, marks: 3, q: "Explain how insulin lowers a raised blood glucose level.", scheme: ["Pancreas detects high glucose and releases insulin", "Body cells take up more glucose", "Liver (and muscles) convert glucose to glycogen for storage"], answer: "When blood glucose is high the pancreas releases insulin, which makes body cells take up more glucose and the liver store the excess as glycogen, lowering the level." },
      { g: 6, marks: 2, q: "Explain how the body raises a low blood glucose level.", scheme: ["Pancreas releases glucagon", "Liver converts stored glycogen back into glucose"], answer: "The pancreas releases glucagon, which makes the liver convert stored glycogen back into glucose, raising the blood glucose level." },
      { g: 6, marks: 2, q: "Explain why insulin must be injected rather than taken as a tablet.", scheme: ["Insulin is a protein", "It would be digested/broken down in the stomach if swallowed"], answer: "Insulin is a protein, so if it were swallowed it would be digested in the stomach and stop working — it must be injected." },
      { g: 6, marks: 3, q: "Explain how blood glucose is controlled by negative feedback.", scheme: ["A rise triggers insulin, which lowers it", "A fall triggers glucagon, which raises it", "This keeps glucose around a set level"], answer: "If blood glucose rises, insulin is released to lower it; if it falls, glucagon is released to raise it. This negative feedback keeps the level around a set point." },
      { g: 6, marks: 2, q: "Explain how the contraceptive pill prevents pregnancy.", scheme: ["Contains hormones (oestrogen/progesterone)", "These stop FSH being produced, so no egg matures"], answer: "The pill contains hormones such as oestrogen and progesterone that inhibit FSH, so no egg matures and pregnancy is prevented." },
      { g: 6, marks: 3, q: "Explain how the eye focuses on a near object.", scheme: ["Ciliary muscles contract", "Suspensory ligaments slacken", "The lens becomes fatter/more curved to refract light more"], answer: "To focus on a near object the ciliary muscles contract and the suspensory ligaments slacken, so the lens becomes fatter and more curved, bending the light more." },
      { g: 6, marks: 3, q: "Explain how the body cools down when it is too hot.", scheme: ["Sweating — evaporation removes heat", "Vasodilation — more blood flows near the skin surface to lose heat", "Hairs lie flat"], answer: "When too hot the body sweats, so evaporation removes heat, and vasodilation brings more blood near the skin surface to radiate heat away, while the hairs lie flat." },
      { g: 6, marks: 3, q: "Explain how the body warms up when it is too cold.", scheme: ["Shivering — muscles contract, respiration releases heat", "Vasoconstriction — less blood near the surface, less heat lost", "Hairs stand up to trap air"], answer: "When too cold the body shivers, so muscle respiration releases heat, vasoconstriction reduces blood flow to the skin to keep heat in, and the hairs stand up to trap an insulating layer of air." },
      { g: 6, marks: 2, q: "Explain how Type 2 diabetes can often be controlled without medication.", scheme: ["A controlled, low-sugar/carbohydrate diet", "Regular exercise and losing weight"], answer: "Type 2 diabetes can often be controlled by eating a carbohydrate-controlled diet, exercising regularly and losing weight." },
      { g: 6, marks: 2, q: "Explain the role of the pancreas in controlling blood glucose.", scheme: ["Monitors the blood glucose level", "Releases insulin (if high) or glucagon (if low)"], answer: "The pancreas monitors the blood glucose level and releases insulin when it is high or glucagon when it is low." },
      { g: 6, marks: 2, q: "Explain the roles of the receptor and effector in a response.", scheme: ["Receptor detects the stimulus/change", "Effector (muscle or gland) carries out the response"], answer: "The receptor detects the stimulus, and the effector — a muscle or gland — carries out the response." },
      { g: 6, marks: 2, q: "Explain why hormonal responses are usually slower but longer-lasting than nervous responses.", scheme: ["Hormones travel in the blood (slower to reach target)", "But remain until broken down, so effects last longer"], answer: "Hormones are carried more slowly in the blood, so they take longer to act, but they remain in the blood until broken down, so their effects last longer than fast, brief nerve impulses." },
      { g: 6, marks: 2, q: "Explain how oestrogen and progesterone maintain the lining of the uterus.", scheme: ["Oestrogen builds up the uterus lining", "Progesterone maintains the lining (and inhibits FSH/LH)"], answer: "Oestrogen builds up the uterus lining after a period, and progesterone maintains it ready for a fertilised egg." },

      // ---------------- GRADE 7 ----------------
      { g: 7, marks: 4, q: "Describe the reflex arc that occurs when a person touches a hot object.", scheme: ["Receptor in the skin detects heat/pain (stimulus)", "Sensory neurone carries impulse to the spinal cord", "Relay neurone passes it to a motor neurone", "Motor neurone to the muscle (effector), which contracts to pull the hand away"], answer: "A heat receptor in the skin detects the stimulus and sends an impulse along a sensory neurone to the spinal cord, where a relay neurone passes it to a motor neurone. This carries the impulse to the arm muscle (the effector), which contracts to pull the hand away." },
      { g: 7, marks: 3, q: "Explain how the structure of a synapse ensures impulses travel in only one direction.", scheme: ["Neurotransmitter is only released from one side of the gap", "Receptors are only on the other (receiving) neurone", "So the signal can only cross one way"], answer: "The neurotransmitter is released only from the transmitting neurone and the receptors are only on the receiving neurone, so the impulse can cross the synapse in one direction only." },
      { g: 7, marks: 4, q: "Explain fully how blood glucose is controlled by negative feedback in both directions.", scheme: ["High glucose: pancreas releases insulin", "Cells take up glucose; liver stores it as glycogen → level falls", "Low glucose: pancreas releases glucagon", "Liver converts glycogen to glucose → level rises"], answer: "When blood glucose is high the pancreas releases insulin, so cells take up glucose and the liver stores it as glycogen, lowering the level. When it is low the pancreas releases glucagon, so the liver converts glycogen back to glucose, raising the level — negative feedback keeping it steady." },
      { g: 7, marks: 4, q: "Compare the causes and treatments of Type 1 and Type 2 diabetes.", scheme: ["Type 1: pancreas produces too little insulin; treated with insulin injections", "Type 2: cells stop responding to insulin (linked to obesity)", "Type 2 controlled by diet, exercise and weight loss", "Both must control blood glucose"], answer: "Type 1 diabetes is caused by the pancreas producing too little insulin and is treated with insulin injections, while Type 2 is caused by cells no longer responding to insulin (often linked to obesity) and is usually controlled by diet, exercise and weight loss." },
      { g: 7, marks: 4, q: "Explain how the interaction of FSH, oestrogen and LH controls the first half of the menstrual cycle.", scheme: ["FSH matures an egg and stimulates oestrogen release", "Oestrogen builds the uterus lining", "Rising oestrogen triggers a surge of LH", "LH causes ovulation"], answer: "FSH matures an egg in the ovary and stimulates the release of oestrogen, which builds up the uterus lining. Rising oestrogen then triggers a surge of LH, which causes ovulation — the release of the egg." },
      { g: 7, marks: 4, q: "Describe how IVF (in vitro fertilisation) is used to treat infertility.", scheme: ["FSH and LH given to stimulate several eggs to mature", "Eggs collected and fertilised with sperm in the lab", "Fertilised eggs develop into embryos", "One or two embryos inserted into the uterus"], answer: "The woman is given FSH and LH to mature several eggs, which are collected and fertilised with sperm in a laboratory. The fertilised eggs develop into embryos, and one or two are then inserted into her uterus." },
      { g: 7, marks: 3, q: "Explain how the eye focuses on a distant object (accommodation).", scheme: ["Ciliary muscles relax", "Suspensory ligaments pull tight", "The lens is pulled thin/less curved to refract light less"], answer: "To focus on a distant object the ciliary muscles relax and the suspensory ligaments pull tight, making the lens thin and less curved so it refracts the light less." },
      { g: 7, marks: 3, q: "Explain what causes short-sightedness (myopia) and how it is corrected.", scheme: ["Light is focused in front of the retina", "Because the eyeball is too long / lens too curved", "Corrected with a concave (diverging) lens"], answer: "In short-sightedness light is focused in front of the retina because the eyeball is too long or the lens too curved, so it is corrected with a concave (diverging) lens." },
      { g: 7, marks: 3, q: "Explain what causes long-sightedness (hyperopia) and how it is corrected.", scheme: ["Light is focused behind the retina", "Because the eyeball is too short / lens too weak", "Corrected with a convex (converging) lens"], answer: "In long-sightedness light is focused behind the retina because the eyeball is too short or the lens too weak, so it is corrected with a convex (converging) lens." },
      { g: 7, marks: 3, q: "Explain how vasodilation and sweating cool the body when it overheats.", scheme: ["Vasodilation: blood vessels near the skin widen, more blood flows near the surface", "More heat radiated/lost to the surroundings", "Sweat evaporates, taking heat energy from the skin"], answer: "In vasodilation the blood vessels near the skin widen so more warm blood flows near the surface and radiates heat away, while sweat on the skin evaporates, taking heat energy with it." },
      { g: 7, marks: 3, q: "Explain how thyroxine controls the metabolic rate by negative feedback.", scheme: ["Low thyroxine → pituitary releases TSH → thyroid makes more thyroxine", "High thyroxine inhibits TSH release", "This keeps thyroxine and metabolic rate steady"], answer: "When thyroxine is low the pituitary releases TSH, which makes the thyroid produce more thyroxine; when thyroxine is high it inhibits TSH release. This negative feedback keeps thyroxine, and so the metabolic rate, steady." },
      { g: 7, marks: 3, q: "Explain the role of adrenaline in preparing the body for 'fight or flight'.", scheme: ["Released by the adrenal glands in fear/stress", "Increases heart rate and blood glucose", "Delivers more oxygen and glucose to muscles for action"], answer: "Adrenaline is released by the adrenal glands in response to fear or stress; it increases the heart rate and blood glucose, delivering more oxygen and glucose to the muscles to prepare the body for action." },
      { g: 7, marks: 3, q: "Explain how auxin causes a shoot to bend towards light (phototropism).", scheme: ["Auxin accumulates on the shaded side of the shoot", "It makes those cells elongate more", "The shoot bends towards the light"], answer: "Auxin gathers on the shaded side of the shoot and makes the cells there elongate more than on the light side, so the shoot bends towards the light." },
      { g: 7, marks: 3, q: "Explain how auxin causes roots and shoots to respond differently to gravity.", scheme: ["Auxin gathers on the lower side of a horizontal root/shoot", "In shoots auxin promotes growth → shoot bends up", "In roots auxin inhibits growth → root bends down"], answer: "Auxin gathers on the lower side of a horizontal root or shoot. In shoots it promotes elongation, so the lower side grows more and the shoot bends upwards, while in roots it inhibits elongation, so the upper side grows more and the root bends downwards." },
      { g: 7, marks: 3, q: "Explain why a reflex response is faster than a normal (conscious) response.", scheme: ["The impulse does not go to the conscious brain for a decision", "It follows a short, fixed pathway through the spinal cord", "So there is less delay"], answer: "In a reflex the impulse does not travel to the conscious part of the brain for a decision but follows a short, fixed pathway through the spinal cord, so the response is much faster." },

      // ---------------- GRADE 8 ----------------
      { g: 8, marks: 4, q: "Explain fully how the body controls blood glucose concentration, including the role of the liver.", scheme: ["Pancreas monitors blood glucose", "High: insulin released → cells take up glucose, liver stores it as glycogen", "Low: glucagon released → liver converts glycogen to glucose", "Negative feedback keeps the level around a set point"], answer: "The pancreas monitors blood glucose. When it is high, insulin is released so cells take up glucose and the liver stores it as glycogen; when it is low, glucagon is released so the liver converts glycogen back to glucose. This negative feedback keeps the level around a set point." },
      { g: 8, marks: 4, q: "Evaluate the treatments available for Type 1 and Type 2 diabetes.", scheme: ["Type 1: insulin injections work well but are lifelong and need careful dosing", "Type 2: diet/exercise/weight loss cheap and effective, but rely on the patient", "Type 2 may also need medication/insulin later", "Judgement: treatment must suit the type and the patient"], answer: "Type 1 is treated with insulin injections, which control glucose well but are lifelong and need careful dosing and monitoring. Type 2 is usually managed by diet, exercise and weight loss, which are cheap and effective but depend on the patient, and it may still need medication later. The best treatment therefore depends on the type of diabetes and the individual." },
      { g: 8, marks: 4, q: "Explain the reflex arc fully and why reflexes are important for survival.", scheme: ["Stimulus → receptor → sensory neurone → relay (spinal cord) → motor neurone → effector → response", "Impulse crosses synapses via neurotransmitters", "Bypasses conscious brain → very fast", "Protects the body from harm automatically"], answer: "In a reflex arc a receptor detects the stimulus and sends an impulse along a sensory neurone to a relay neurone in the spinal cord, then along a motor neurone to an effector that responds; the impulse crosses synapses by neurotransmitters. Because it bypasses the conscious brain it is very fast, automatically protecting the body from harm." },
      { g: 8, marks: 4, q: "Explain how the four hormones of the menstrual cycle interact, including feedback.", scheme: ["FSH matures egg and stimulates oestrogen", "Oestrogen builds the uterus lining and triggers LH (and inhibits FSH)", "LH causes ovulation", "Progesterone maintains the lining and inhibits FSH and LH; its fall causes menstruation"], answer: "FSH matures an egg and stimulates oestrogen, which builds the uterus lining and triggers an LH surge while inhibiting further FSH. LH causes ovulation, after which progesterone maintains the lining and inhibits FSH and LH; when progesterone falls the lining breaks down as a period." },
      { g: 8, marks: 4, q: "Evaluate hormonal and barrier methods of contraception.", scheme: ["Hormonal (pill/implant): very effective, but side effects and no STI protection", "Barrier (condom): protects against STIs, no hormones, but can fail/slip", "Reliability and protection differ", "Judgement: choice depends on needs"], answer: "Hormonal methods such as the pill or implant are very effective at preventing pregnancy but can have side effects and give no protection against STIs. Barrier methods like condoms protect against STIs and use no hormones but can fail or slip. The best choice depends on whether reliability, STI protection or avoiding hormones matters most." },
      { g: 8, marks: 4, q: "Explain how the eye accommodates for near and far objects and how common defects are corrected.", scheme: ["Near: ciliary muscles contract, ligaments loosen, lens fatter", "Far: ciliary muscles relax, ligaments tighten, lens thinner", "Myopia (focus in front): concave lens", "Hyperopia (focus behind): convex lens"], answer: "For near objects the ciliary muscles contract, the ligaments loosen and the lens becomes fatter; for far objects the muscles relax, the ligaments tighten and the lens becomes thinner. Short-sightedness, where light focuses in front of the retina, is corrected with a concave lens, and long-sightedness, where it focuses behind, with a convex lens." },
      { g: 8, marks: 4, q: "Explain thermoregulation as a negative feedback system.", scheme: ["Temperature receptors detect a change from normal", "The brain (thermoregulatory centre) coordinates a response", "Too hot: sweating and vasodilation lose heat", "Too cold: shivering and vasoconstriction conserve/generate heat — returning temperature to normal"], answer: "Temperature receptors detect a change from the normal body temperature, and the brain's thermoregulatory centre coordinates a response: if too hot, sweating and vasodilation lose heat; if too cold, shivering and vasoconstriction generate and conserve heat. This negative feedback returns the temperature to normal." },
      { g: 8, marks: 3, q: "Analyse why a diabetic's blood glucose rises much higher than a non-diabetic's after a sugary meal.", scheme: ["Both absorb glucose, raising blood glucose", "Non-diabetic releases insulin → glucose taken up/stored → level falls", "Diabetic lacks insulin (or cells don't respond) → glucose stays high"], answer: "After the meal both people absorb glucose, but a non-diabetic releases insulin so the glucose is taken up and stored and the level falls. A diabetic either lacks insulin or their cells don't respond, so the glucose is not removed and stays high." },
      { g: 8, marks: 3, q: "Explain how thyroxine and adrenaline differ in how their release is controlled.", scheme: ["Thyroxine: released steadily, controlled by negative feedback (TSH)", "Adrenaline: released quickly in response to fear/stress", "Adrenaline is not controlled by negative feedback in the same way"], answer: "Thyroxine is released steadily and controlled by negative feedback through TSH to keep the metabolic rate constant, whereas adrenaline is released rapidly in response to fear or stress and is not regulated by the same negative feedback." },
      { g: 8, marks: 4, q: "Explain the role of auxins in phototropism and gravitropism, with reasoning.", scheme: ["Auxin is a plant hormone that controls cell elongation", "Phototropism: auxin moves to the shaded side → shoot bends to light", "Gravitropism in shoots: auxin on lower side promotes growth → bends up", "In roots: auxin on lower side inhibits growth → bends down"], answer: "Auxin controls cell elongation. In phototropism it moves to the shaded side of a shoot, which elongates so the shoot bends towards the light. In gravitropism auxin gathers on the lower side: in shoots it promotes growth so they bend up, while in roots it inhibits growth so they bend down." },
      { g: 8, marks: 4, q: "Evaluate the use of plant hormones in agriculture.", scheme: ["Auxins as weedkillers (selective) and in rooting powder", "Ethene ripens fruit; gibberellins end seed dormancy", "Benefits: higher yields, control of growth/ripening", "Drawbacks: cost, possible overuse/environmental effects"], answer: "Plant hormones are used as selective weedkillers and rooting powders (auxins), to ripen fruit (ethene) and to end seed dormancy (gibberellins). They increase yields and give control over growth and ripening, but they cost money and their overuse can have environmental effects, so their benefits must be weighed against these drawbacks." },
      { g: 8, marks: 3, q: "Explain the difference between nervous and hormonal coordination using an example of each.", scheme: ["Nervous: fast, electrical, short-lived — e.g. a reflex to pull away from heat", "Hormonal: slower, chemical, longer-lasting — e.g. insulin controlling blood glucose"], answer: "Nervous coordination is fast, electrical and short-lived, such as a reflex pulling a hand from a hot object, while hormonal coordination is slower, chemical and longer-lasting, such as insulin controlling blood glucose over time." },
      { g: 8, marks: 3, q: "Explain how ADH helps control the water content of the blood.", scheme: ["If blood is too concentrated, more ADH is released", "The kidney reabsorbs more water → less, more concentrated urine", "If blood is too dilute, less ADH → more dilute urine"], answer: "When the blood is too concentrated more ADH is released, making the kidneys reabsorb more water so less, more concentrated urine is produced; when the blood is too dilute less ADH is released and more dilute urine is made — keeping the water content steady." },
      { g: 8, marks: 4, q: "Evaluate IVF as a treatment for infertility.", scheme: ["Gives infertile couples the chance of a baby", "But success rates are relatively low", "Expensive and emotionally/physically stressful", "Risk of multiple births; some ethical objections", "Judgement weighing benefits against drawbacks"], answer: "IVF gives infertile couples a chance of having a baby, but success rates are relatively low, it is expensive and physically and emotionally stressful, and it carries a risk of multiple births as well as ethical objections. Whether it is worthwhile depends on weighing the strong desire for a child against these drawbacks." },
      { g: 8, marks: 3, q: "Explain how the central nervous system coordinates a response from stimulus to effector.", scheme: ["Receptors detect the stimulus and send impulses to the CNS", "The CNS (brain/spinal cord) processes the information", "It sends impulses along motor neurones to effectors, which respond"], answer: "Receptors detect the stimulus and send impulses to the CNS, where the brain or spinal cord processes the information and sends impulses along motor neurones to the effectors, which carry out the response." },

      // ---------------- GRADE 9 ----------------
      { g: 9, marks: 6, q: "Explain fully how blood glucose is controlled in both directions and what goes wrong in Type 1 and Type 2 diabetes.", scheme: ["Pancreas monitors glucose", "High: insulin → uptake by cells, liver stores glycogen", "Low: glucagon → liver releases glucose from glycogen", "Negative feedback around a set point", "Type 1: too little insulin produced → injections needed", "Type 2: cells stop responding to insulin → diet/exercise/weight loss"], answer: "The pancreas monitors blood glucose: when high, insulin makes cells take up glucose and the liver store it as glycogen; when low, glucagon makes the liver release glucose. This negative feedback keeps it around a set point. In Type 1 diabetes the pancreas makes too little insulin, so injections are needed, while in Type 2 the cells stop responding to insulin, usually managed by diet, exercise and weight loss." },
      { g: 9, marks: 6, q: "Compare nervous and hormonal control, explaining when each is more useful, with examples.", scheme: ["Nervous: electrical impulses, very fast, precise target, short-lived", "Useful for rapid responses (reflexes, movement)", "Hormonal: chemical in blood, slower, widespread, longer-lasting", "Useful for longer-term/whole-body changes (growth, menstrual cycle, glucose)", "Both coordinated by the body; example of each"], answer: "Nervous control uses fast electrical impulses to precise targets but is short-lived, so it suits rapid responses such as reflexes and movement. Hormonal control uses chemicals carried in the blood, so it is slower and more widespread but longer-lasting, suiting whole-body or long-term changes such as growth, the menstrual cycle and blood glucose regulation." },
      { g: 9, marks: 6, q: "Explain the complete reflex arc and evaluate why reflexes are protective.", scheme: ["Stimulus → receptor → sensory neurone", "Relay neurone in the spinal cord/CNS", "Motor neurone → effector → response", "Synapses ensure one-way transmission", "Bypasses conscious brain → fast and automatic", "Protective: e.g. removing hand from heat, blinking — reduces harm"], answer: "In a reflex arc a receptor detects the stimulus and sends an impulse along a sensory neurone to a relay neurone in the spinal cord, then along a motor neurone to an effector that responds, with synapses ensuring one-way transmission. Because it bypasses the conscious brain it is fast and automatic, protecting the body — for example pulling the hand from heat or blinking — by reducing harm before we can think." },
      { g: 9, marks: 6, q: "Explain how the four menstrual cycle hormones interact through feedback to control the cycle.", scheme: ["FSH matures an egg and stimulates oestrogen", "Oestrogen builds the lining, triggers LH, inhibits FSH", "LH surge causes ovulation", "Progesterone maintains the lining and inhibits FSH and LH", "Fall in progesterone → menstruation and FSH rises again", "Feedback links each hormone"], answer: "FSH matures an egg and stimulates oestrogen, which builds the uterus lining, triggers an LH surge and inhibits further FSH. The LH surge causes ovulation, after which progesterone maintains the lining and inhibits FSH and LH. When progesterone falls the lining is shed as a period and FSH rises again, restarting the cycle — each hormone controlling the next through feedback." },
      { g: 9, marks: 6, q: "Evaluate the use of hormones to treat infertility, including FSH treatment and IVF.", scheme: ["FSH/LH ('fertility drugs') stimulate egg maturation/ovulation", "IVF fertilises eggs outside the body and implants embryos", "Benefits: help couples who cannot conceive naturally", "Drawbacks: low success, expensive, stressful", "Risk of multiple births; ethical concerns over spare embryos", "Justified conclusion"], answer: "Fertility drugs containing FSH and LH stimulate eggs to mature and be released, and IVF fertilises eggs outside the body before implanting embryos. These help couples who cannot conceive naturally, but success rates are low, the treatments are expensive and stressful, there is a risk of multiple births, and there are ethical concerns about unused embryos — so their use must be weighed against these issues." },
      { g: 9, marks: 6, q: "Explain how the eye focuses light on the retina and how myopia and hyperopia are corrected, with ray reasoning.", scheme: ["Light refracted by the cornea and lens onto the retina", "Accommodation changes lens shape for near/far objects", "Myopia: image forms in front of the retina → concave lens diverges light first", "Hyperopia: image forms behind the retina → convex lens converges light first", "So the image forms on the retina"], answer: "The cornea and lens refract light to focus it on the retina, with the lens changing shape (accommodation) for near and far objects. In myopia the image forms in front of the retina, so a concave lens is used to diverge the light slightly first; in hyperopia it forms behind the retina, so a convex lens converges it first — in both cases making the image fall on the retina." },
      { g: 9, marks: 6, q: "Explain thermoregulation as a negative feedback system, including the role of the brain.", scheme: ["Thermoregulatory centre in the brain monitors blood temperature", "Temperature receptors in the skin detect external temperature", "Too hot: sweating, vasodilation, hairs flat → lose heat", "Too cold: shivering, vasoconstriction, hairs raised → gain/conserve heat", "Responses reverse the change back to normal (negative feedback)"], answer: "The thermoregulatory centre in the brain monitors the temperature of the blood, and skin receptors detect the external temperature. If too hot, sweating and vasodilation (and hairs lying flat) lose heat; if too cold, shivering and vasoconstriction (and hairs standing up) generate and conserve heat. These responses reverse the change, returning the temperature to normal by negative feedback." },
      { g: 9, marks: 6, q: "Explain how ADH controls the water content of the blood by negative feedback via the kidney.", scheme: ["Water content monitored (by the brain/hypothalamus)", "Blood too concentrated: pituitary releases more ADH", "Kidney tubules reabsorb more water → little, concentrated urine", "Blood too dilute: less ADH released", "Kidney reabsorbs less water → lots of dilute urine", "This reverses the change (negative feedback)"], answer: "The brain monitors the blood's water content. If the blood is too concentrated, the pituitary releases more ADH, making the kidney tubules reabsorb more water so only a little concentrated urine is made; if too dilute, less ADH is released so the kidney reabsorbs less and produces plenty of dilute urine. This negative feedback keeps the water content constant." },
      { g: 9, marks: 5, q: "Explain how auxins produce both phototropic and gravitropic responses, and give two commercial uses.", scheme: ["Auxin controls cell elongation and moves within the plant", "Phototropism: auxin to shaded side → shoot bends to light", "Gravitropism: auxin to lower side; promotes shoot growth (up), inhibits root growth (down)", "Uses: selective weedkillers; rooting powder for cuttings (any two)"], answer: "Auxin controls cell elongation and redistributes within the plant: in phototropism it moves to the shaded side so the shoot bends towards light, and in gravitropism it gathers on the lower side, promoting shoot growth (bending up) but inhibiting root growth (bending down). Commercially, auxins are used as selective weedkillers and in rooting powder to help cuttings grow roots." },
      { g: 9, marks: 6, q: "Explain how the nervous and endocrine systems work together in the 'fight or flight' response.", scheme: ["Brain detects a threat (nervous)", "Signals the adrenal glands", "Adrenal glands release adrenaline (hormonal)", "Adrenaline raises heart rate, breathing and blood glucose", "More oxygen and glucose to muscles for action", "Nervous system is fast to trigger; hormone sustains the response"], answer: "The brain detects a threat and, through the nervous system, signals the adrenal glands to release the hormone adrenaline. Adrenaline increases heart rate, breathing and blood glucose, delivering more oxygen and glucose to the muscles ready for action. The nervous system triggers the response quickly while the hormone sustains it — the two systems working together." },
      { g: 9, marks: 5, q: "Analyse blood glucose data for a person over a day and recommend how a Type 2 diabetic could manage their condition.", scheme: ["After meals glucose rises; insulin normally lowers it", "In Type 2 the fall is slow/incomplete (cells resist insulin)", "Recommend a low-sugar/carbohydrate, balanced diet", "Regular exercise increases glucose uptake by muscles", "Lose weight; monitor glucose; medication if needed"], answer: "The data show glucose rising after meals and, in a Type 2 diabetic, falling slowly because the cells resist insulin. To manage it, they should eat a balanced, low-sugar diet, exercise regularly so muscles take up more glucose, lose weight, monitor their blood glucose, and take medication if lifestyle changes are not enough." },
      { g: 9, marks: 6, q: "Explain the full homeostatic control of body temperature, naming the receptor, coordination centre and effectors.", scheme: ["Receptors: temperature receptors in the skin and brain", "Coordination centre: thermoregulatory centre in the brain", "Effectors when hot: sweat glands (sweating), skin arterioles (vasodilation)", "Effectors when cold: muscles (shivering), skin arterioles (vasoconstriction), hair erector muscles", "Negative feedback returns temperature to normal"], answer: "Temperature receptors in the skin and brain detect changes, and the thermoregulatory centre in the brain coordinates the response. When too hot the effectors are the sweat glands (sweating) and skin arterioles (vasodilation); when too cold they are the muscles (shivering), skin arterioles (vasoconstriction) and hair erector muscles. These reverse the change back to normal by negative feedback." },
      { g: 9, marks: 5, q: "Evaluate lifestyle changes versus medication for managing Type 2 diabetes.", scheme: ["Lifestyle (diet, exercise, weight loss): tackles the cause, cheap, no side effects", "But relies on the patient's commitment", "Medication/insulin: reliable control, but cost and side effects, doesn't cure", "Often used together", "Justified conclusion favouring lifestyle first"], answer: "Lifestyle changes such as diet, exercise and weight loss tackle the underlying cause of Type 2 diabetes, are cheap and have no side effects, but they rely on the patient's commitment. Medication or insulin controls glucose reliably but costs money, can have side effects and does not cure the condition. They are often combined, with lifestyle change usually the first and best approach." },
      { g: 9, marks: 6, q: "Explain how thyroxine controls metabolic rate through negative feedback, including the role of the pituitary gland.", scheme: ["Thyroxine from the thyroid controls metabolic rate/growth", "Pituitary releases TSH which stimulates the thyroid", "Low thyroxine → more TSH → more thyroxine made", "High thyroxine inhibits TSH release", "This negative feedback keeps thyroxine steady", "Steady thyroxine keeps a steady metabolic rate"], answer: "Thyroxine, released by the thyroid, controls the body's metabolic rate. The pituitary releases TSH, which stimulates the thyroid: when thyroxine is low, more TSH is released so more thyroxine is made, and when it is high, TSH release is inhibited. This negative feedback keeps thyroxine, and therefore the metabolic rate, steady." },
      { g: 9, marks: 5, q: "Design an investigation into the effect of the direction of light on the growth of seedlings, and justify your method.", scheme: ["Grow seedlings; expose groups to light from different directions (one side, above, all-round, dark)", "Keep temperature, water, seedling type and light intensity the same", "Measure the direction/angle of shoot growth after several days", "Repeat with several seedlings and take means", "Justify: controls isolate the effect of light direction (phototropism)"], answer: "Grow similar seedlings and expose groups to light from different directions — one side, from above, all around, and darkness — keeping temperature, water, seedling type and light intensity the same. After a few days measure the direction the shoots grow, using several seedlings per group and taking means. Controlling the other variables ensures any difference in growth direction is due to the light direction (phototropism), making the result valid." },
    ],
  },
}
